/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A21: 80 frozen lemmas, audited in four exact 20-word checkpoints. */
'use strict';
const D = globalThis.RA.D;
const E = (origin, word) => ({origin, prefix:null, root:null, suffix:null, source:'Etymonline, https://www.etymonline.com/word/'+word.toLowerCase()});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M = (wrong,right,reason,errorType='meaning') => ({wrong,right,reason,errorType});
const Q = (w,n,sense,prompt,options,answer,explain,errorType='meaning') => ({id:w+'.q'+n,senseId:w+'.s'+sense,errorType,type:'辨义与用法',prompt,options,answer,explain});
D('crystalline',{etymology:E('crystalline entered English through French from Latin crystallinus, from Greek krystallinos “of crystal”; it describes crystal-like clarity or a crystal structure.','crystalline'),contexts:[C('crystalline.s1','湖泊景色','By sunrise the spring-fed pool was crystalline, so hikers could see pale stones resting several metres below the surface.','日出时泉水注入的水潭清澈如水晶，徒步者能看见水面下几米处的浅色石子。','By sunrise / the spring-fed pool was crystalline / so hikers could see pale stones / resting several metres below the surface.','crystalline 作表语形容词，描述水体的清澈透明。','石子透过水面清晰可见，体现“水晶般清澈”义 s1。'),C('crystalline.s2','矿物学','The geologist photographed a crystalline pattern in the cooled mineral, whose tiny grains had arranged themselves into a repeating lattice.','地质学家拍下冷却矿物中的结晶结构，其中细小颗粒排列成重复的晶格。','The geologist photographed a crystalline pattern / in the cooled mineral / whose tiny grains had arranged themselves into a repeating lattice.','crystalline 修饰 pattern，指晶体排列形成的结构。','重复晶格是晶体结构特征，符合 s2。')],mistakes:[M('The cloudy liquid was crystalline, and no light or object could be seen through it.','The cloudy liquid was opaque, and no light or object could be seen through it.','完全浑浊不透明的液体不能称为清澈透明的 crystalline。')],quiz:[Q('crystalline',1,1,'Which scene best illustrates crystalline water?',['A swimmer can count pebbles on the lake bed.','Silt hides everything beneath the surface.','Oil forms an opaque layer across the pond.'],'A swimmer can count pebbles on the lake bed.','Visible details below the surface signal crystal-like clarity.'),Q('crystalline',2,2,'A mineral has atoms in an orderly repeating lattice. Its structure is?',['crystalline','amorphous','gaseous'],'crystalline','Crystalline describes matter whose particles form an ordered crystal structure.'),Q('crystalline',3,1,'In “crystalline prose,” the figurative emphasis is usually on prose that is?',['exceptionally clear','deliberately confusing','written only in verse'],'exceptionally clear','The clarity sense extends metaphorically to language.'),Q('crystalline',4,2,'Choose the scientific use of crystalline.',['The salt formed crystalline grains as the solution evaporated.','The fog made the road crystalline and invisible.','The liquid stayed crystalline despite having no ordered solids.'],'The salt formed crystalline grains as the solution evaporated.','Evaporation can leave solid crystals, matching the material sense.') ]});
D('crystallization',{etymology:E('crystallization is formed from crystallize plus the process noun suffix -ation; crystallize derives from crystal, ultimately Greek krystallos.','crystallization'),contexts:[C('crystallization.s1','化学实验','Slow cooling encouraged crystallization, and white salt crystals appeared along the rim of the shallow dish.','缓慢冷却促进了结晶，浅盘边缘逐渐出现白色盐晶体。','Slow cooling encouraged crystallization / and white salt crystals appeared / along the rim of the shallow dish.','crystallization 作不可数名词，指形成晶体的过程。','盐由溶液析出为晶体，正是物质结晶过程 s1。'),C('crystallization.s2','政策形成','The committee’s crystallization of the proposal took months: scattered suggestions gradually became a precise, agreed policy.','委员会把提案逐步具体化用了好几个月：零散建议渐渐变成明确且获得认可的政策。','The committee’s crystallization of the proposal took months / scattered suggestions gradually became / a precise, agreed policy.','名词 crystallization of + 抽象事物表示其逐渐具体成形。','想法从模糊建议变成定型政策，对应比喻义 s2。')],mistakes:[M('After the salt crystals formed, the continued crystallization of the solution meant that every crystal immediately dissolved.','After the salt crystals formed, the continued dissolution of the solution meant that the crystals disappeared.','crystallization 是形成晶体，不是晶体溶解消失；反向过程是 dissolution。','confusable')],quiz:[Q('crystallization',1,1,'What is crystallization in a cooling salt solution?',['The formation of solid salt crystals.','The melting of salt into a gas.','The stirring of salt without any change.'],'The formation of solid salt crystals.','Crystallization names the process in which crystals form.'),Q('crystallization',2,2,'A vague plan becomes a clearly defined program. This is figurative?',['crystallization of the plan','evaporation of the plan','fragmentation of the plan'],'crystallization of the plan','The figurative sense is the gradual emergence of a definite form.'),Q('crystallization',3,1,'Which condition may promote crystallization from a solution?',['Careful cooling that lets crystals grow.','Adding heat until all solids vaporize.','Filtering away every particle before the solution changes.'],'Careful cooling that lets crystals grow.','Cooling can bring a dissolved substance out as crystals.'),Q('crystallization',4,2,'The phrase “the crystallization of public opinion” suggests that opinion?',['became more definite and unified','turned into a mineral physically','was erased from public discussion'],'became more definite and unified','Here crystallization is metaphorical: an unclear view takes definite shape.') ]});
D('crystallize',{etymology:E('crystallize is formed from crystal, via French and Latin from Greek krystallos, with the verb-forming -ize; it means form crystals or become definite.','crystallize'),contexts:[C('crystallize.s1','制糖工艺','As the syrup cooled, sugar began to crystallize on the wooden spoon, leaving a thin layer of sparkling grains.','糖浆冷却时，糖开始在木勺上结晶，留下一层闪亮的颗粒。','As the syrup cooled / sugar began to crystallize on the wooden spoon / leaving a thin layer of sparkling grains.','crystallize 可不及物，表示物质形成晶体。','糖从糖浆析出为颗粒，符合物理结晶义 s1。'),C('crystallize.s2','方案定稿','The interviews helped the team’s priorities crystallize: access for rural patients became the first goal.','访谈帮助团队明确了优先事项：让乡村患者获得服务成为首要目标。','The interviews helped the team’s priorities crystallize / access for rural patients became the first goal.','抽象主语 priorities 作不及物用法，表示逐渐清晰确定。','原本分散的优先考虑明确成首要目标，符合比喻义 s2。')],mistakes:[M('The sugar crystallized into a clear liquid as the syrup cooled.','The sugar dissolved into a clear liquid as the syrup warmed.','结晶会形成固体晶体，不会变成透明液体；液体化应为溶解且通常需适当条件。')],quiz:[Q('crystallize',1,1,'When dissolved sugar crystallizes, it?',['forms solid sugar crystals','turns into oxygen','vanishes without leaving matter'],'forms solid sugar crystals','The verb describes crystals forming out of a solution.'),Q('crystallize',2,2,'After several meetings, the proposal crystallized. What happened?',['It became clearer and more definite.','It physically became a gemstone.','It disappeared from the agenda.'],'It became clearer and more definite.','The figurative sense is to take a definite form.'),Q('crystallize',3,1,'Which sentence uses crystallize literally?',['Ice crystals crystallized along the window edge.','The group’s shared purpose crystallized after debate.','Her explanation crystallized the team’s vague priorities.'],'Ice crystals crystallized along the window edge.','Ice crystals physically formed on the cold surface.'),Q('crystallize',4,2,'A disagreement crystallizes around one central issue. The issue has?',['become the clear focus of the dispute','turned into a physical crystal','been settled without anyone noticing'],'become the clear focus of the dispute','The figurative verb marks a matter taking a definite, central shape.') ]});
D('crystallized',{etymology:E('crystallized is the past form and participial adjective of crystallize, itself from crystal plus -ize; in British English the spelling crystallised is also used.','crystallized'),contexts:[C('crystallized.s1','地质样本','The crystallized mineral was harder than the surrounding glassy material and showed sharply edged facets under the microscope.','结晶矿物比周围玻璃状物质更硬，在显微镜下呈现边缘清晰的晶面。','The crystallized mineral was harder than the surrounding glassy material / and showed sharply edged facets / under the microscope.','crystallized 作前置形容词，说明矿物已经形成晶体。','晶面清晰、已呈晶体形态，对应 s1。'),C('crystallized.s2','谈判结果','By Friday the committee had a crystallized position on funding, with a fixed ceiling and named priorities.','到周五，委员会对经费已有明确立场，设定了固定上限并列出了优先事项。','By Friday the committee had a crystallized position on funding / with a fixed ceiling and named priorities.','crystallized 修饰 position，表示观点已成形且明确。','预算上限及优先次序表明立场已经具体化，符合 s2。')],mistakes:[M('The committee adopted a crystallized plan, but its priorities remained vague and no decisions had been made.','The committee adopted an unresolved plan, because its priorities remained vague and no decisions had been made.','若内容仍模糊且未作决定，就不能称为已明确成形的 crystallized plan。')],quiz:[Q('crystallized',1,1,'A crystallized deposit consists of material that has?',['formed crystals','remained entirely gaseous','been turned into a liquid only'],'formed crystals','The adjective can describe matter that has formed crystals.'),Q('crystallized',2,2,'The group has a crystallized view of the issue. Its view is?',['clearly defined','still completely formless','unrelated to the issue'],'clearly defined','The figurative participle means that an idea has become definite.'),Q('crystallized',3,1,'Which clue most strongly supports the literal use of crystallized?',['The sample has a regular lattice and visible crystal faces.','The plan lists three precise goals.','The voters reached agreement after debate.'],'The sample has a regular lattice and visible crystal faces.','A lattice and crystal faces point to the material sense.'),Q('crystallized',4,2,'Choose a natural figurative phrase.',['a crystallized consensus on next steps','a crystallized mist that has no fixed shape','a crystallized rumor that nobody can define'],'a crystallized consensus on next steps','A consensus can become definite or settled.') ]});
D('Cuban',{etymology:E('Cuban is formed from Cuba, the name of the Caribbean island and country, plus the demonym suffix -an; it can be a noun or adjective.','Cuban'),contexts:[C('Cuban.s1','国籍与身份','A Cuban who had moved to Montreal still cooked the black beans her grandmother taught her to make in Havana.','一位搬到蒙特利尔的古巴人仍按祖母在哈瓦那教的方法烹煮黑豆。','A Cuban who had moved to Montreal / still cooked the black beans / her grandmother taught her to make in Havana.','Cuban 作可数名词，指来自古巴的人；关系从句修饰该名词。','句中人物来自古巴，符合人的国籍/身份义 s1。'),C('Cuban.s2','音乐文化','The festival opened with Cuban music, including a son ensemble whose syncopated rhythm brought dancers onto the plaza.','节庆以古巴音乐开场，其中一支演奏古巴 son 的乐队用切分节奏吸引舞者来到广场。','The festival opened with Cuban music / including a son ensemble / whose syncopated rhythm brought dancers onto the plaza.','Cuban 作定语形容词，说明音乐与古巴的关联。','son 是古巴音乐传统之一，语境为古巴的事物义 s2。')],mistakes:[M('Nora is a Cuban from Cuba, so she is a person from Canada.','Nora is a Cuban from Cuba, so she is a person from Cuba.','Cuban 指古巴人，不能由此推出加拿大国籍；错误将国名和国籍混淆。','word-formation')],quiz:[Q('Cuban',1,1,'A Cuban is a person from?',['Cuba','Cuba’s neighbor Jamaica','the Canadian province of Quebec'],'Cuba','Cuban names a person from Cuba.'),Q('Cuban',2,2,'Which phrase uses Cuban adjectivally?',['Cuban coffee served at the Havana café','a Cuban arrived from the island','two Cubans waited outside'],'Cuban coffee served at the Havana café','Here Cuban modifies the noun coffee.'),Q('Cuban',3,1,'A family described as Cuban most directly has a connection to?',['Cuba','Cuba’s currency only, with no other connection','the word cubic'],'Cuba','Cuban is the nationality or relational adjective formed from Cuba.'),Q('Cuban',4,2,'In “Cuban artists exhibited in Madrid,” Cuban tells the reader?',['the artists’ national or cultural association','that the artists make cubes','that the exhibition took place in Cuba'],'the artists’ national or cultural association','The adjective attributes a connection to Cuba, not the exhibition venue.') ]});
D('cubic',{etymology:E('cubic came through French cubique from Latin cubicus and Greek kubikos, “having the form of a cube”; it also names a unit based on volume.','cubic'),contexts:[C('cubic.s1','几何形状','The architect used a cubic pavilion, with six equal square faces and no longer side to interrupt its compact outline.','建筑师采用了立方体形的亭子，六个面都是相等的正方形，外形紧凑而没有较长的一边。','The architect used a cubic pavilion / with six equal square faces / and no longer side to interrupt its compact outline.','cubic 作形容词，描述具有立方体形状或特征的物体。','六个相等正方形面符合立方体几何形状义 s1。'),C('cubic.s2','体积计量','The aquarium holds 2,000 cubic centimetres of water, a volume equivalent to two litres.','这个水族箱能装 2,000 立方厘米的水，相当于两升。','The aquarium holds 2,000 cubic centimetres of water / a volume equivalent to two litres.','cubic + 长度单位表示三维体积单位。','立方厘米是体积而非长度单位，符合计量义 s2。')],mistakes:[M('The crate has a cubic shape because it is a long rectangular box with unequal dimensions.','The crate has a rectangular shape because it is a long box with unequal dimensions.','cubic 指立方体形状，长宽高不等的长箱不满足此形状。')],quiz:[Q('cubic',1,1,'A cubic box has?',['the shape of a cube','the shape of a flat circle','only one measurable dimension'],'the shape of a cube','Cubic means cube-shaped.'),Q('cubic',2,2,'A cubic metre measures?',['volume','temperature','distance along a road'],'volume','Cubed length units measure three-dimensional volume.'),Q('cubic',3,1,'Which object is most clearly cubic?',['a die with equal square faces','a long pipe','a circular dinner plate'],'a die with equal square faces','A standard die is approximately cube-shaped.'),Q('cubic',4,2,'A tank has a capacity of 3 cubic metres. The number describes?',['how much three-dimensional space it holds','the length of its longest edge alone','the number of sides it has'],'how much three-dimensional space it holds','Cubic metres are a unit of volume.') ]});
D('cubicle',{etymology:E('cubicle came through Latin cubiculum “bedchamber,” from cubare “lie down”; English narrowed it to a small partitioned room or work space.','cubicle'),contexts:[C('cubicle.s1','办公室布局','Each analyst had a small cubicle separated by fabric panels, so coworkers could speak quietly without occupying a private office.','每位分析员都有一个用布面隔板分开的办公小隔间，同事可以轻声交谈，却不必占用独立办公室。','Each analyst had a small cubicle / separated by fabric panels / so coworkers could speak quietly / without occupying a private office.','cubicle 作可数名词；过去分词短语说明小隔间的分隔方式。','布面隔板划出办公小空间，符合 s1。')],mistakes:[M('She booked a cubicle for the meeting, a large open-air field with no partitions or walls.','She booked a conference room for the meeting, a large space with no individual partitions.','cubicle 通常是有隔板的小空间；大型开放场地不符合其含义。')],quiz:[Q('cubicle',1,1,'An office cubicle is usually?',['a small workspace divided by partitions','a whole multi-storey office tower','a seat in an outdoor stadium'],'a small workspace divided by partitions','Cubicles are compact, partitioned work areas.'),Q('cubicle',2,1,'Which place is most likely to contain several cubicles?',['an open-plan office','a single-family garden shed with one room','a public highway'],'an open-plan office','Offices often arrange small partitioned workstations in a shared room.'),Q('cubicle',3,1,'A worker closes the low door of a changing cubicle. The cubicle provides?',['a small private space','a large public stage','a vehicle for transporting clothes'],'a small private space','A cubicle is a small enclosed or partitioned space.'),Q('cubicle',4,1,'Choose a natural collocation.',['an office cubicle','a cubicle of ocean water','a cubicle of three kilometres'],'an office cubicle','Office cubicle is a common phrase for a partitioned workstation.') ]});
D('cubism',{etymology:E('cubism was coined from cube with the art movement suffix -ism; the name became associated with early twentieth-century painters who depicted forms through geometric facets.','cubism'),contexts:[C('cubism.s1','现代艺术','The curator compared two Cubist portraits, noting how a profile and a pair of eyes appeared from different viewpoints on the same canvas.','策展人比较了两幅立体主义肖像，指出同一画布上的侧脸和一双眼睛仿佛来自不同视角。','The curator compared two Cubist portraits / noting how a profile and a pair of eyes appeared / from different viewpoints on the same canvas.','Cubist 是由 cubism 派生的形容词；作品将多个视角并置。','同一画面呈现不同视角，是立体主义的典型表现，体现艺术运动 s1。')],mistakes:[M('The museum labeled a photograph of one object from a single viewpoint as cubism because it contained no geometric fragmentation.','The museum labeled the painting cubism because it broke the object into geometric facets and combined viewpoints.','单一视角且无几何分解不能说明立体主义；错误描述与该艺术流派特征相反。')],quiz:[Q('cubism',1,1,'Cubism is best known as a movement in?',['modern visual art','astronomy','culinary medicine'],'modern visual art','Cubism is an influential modern art movement.'),Q('cubism',2,1,'A cubist painting may show one face?',['from more than one viewpoint at once','only as a perfectly realistic snapshot','as a sequence of written recipes'],'from more than one viewpoint at once','Cubist artists often combine multiple viewpoints in one image.'),Q('cubism',3,1,'Which description most closely fits cubism?',['Forms are broken into geometric planes.','Every object is copied as a single photographic view.','A painting consists only of musical notes.'],'Forms are broken into geometric planes.','Geometric fragmentation is central to many Cubist works.'),Q('cubism',4,1,'A critic discussing cubism is most likely to analyze?',['how a painter reassembled objects from facets and angles','the chemical taste of a stew','the speed of a bicycle race'],'how a painter reassembled objects from facets and angles','This describes the movement’s formal approach to depicting objects.') ]});
D('cud',{etymology:E('cud is a native English word recorded in Middle English; its deeper origin is uncertain. It names food returned by a ruminant for further chewing.','cud'),contexts:[C('cud.s1','反刍动物','The cow lay beneath the shade tree chewing her cud, slowly grinding the partly digested grass she had brought back from her first stomach.','奶牛躺在树荫下反刍，把从第一个胃返回口中的半消化牧草慢慢嚼碎。','The cow lay beneath the shade tree / chewing her cud / slowly grinding the partly digested grass / she had brought back from her first stomach.','cud 作不可数名词；chew one’s cud 是“反刍”的常见搭配。','草料从反刍动物胃中返回口腔再次咀嚼，符合 s1。')],mistakes:[M('The rabbit chewed its cud after swallowing food into a single-chambered stomach.','The rabbit chewed its food after swallowing it; cows chew cud as ruminants.','兔不是反刍动物；cud 特指反刍动物返回口中再嚼的食物。','confusable')],quiz:[Q('cud',1,1,'A cow chewing the cud is?',['bringing up and rechewing partly digested food','eating only newly cut hay for the first time','grinding food with its horns'],'bringing up and rechewing partly digested food','Cud is food returned by a ruminant for further chewing.'),Q('cud',2,1,'Which animal commonly chews cud?',['a sheep','a swallow','a salmon'],'a sheep','Sheep are ruminants and rechew cud.'),Q('cud',3,1,'The noun cud refers to?',['partly digested food rechewed by a ruminant','a cow’s horn','a patch of grass before it is eaten'],'partly digested food rechewed by a ruminant','The term names the regurgitated food itself.'),Q('cud',4,1,'In “He sat and chewed the problem over like cud,” cud is used?',['figuratively, for something considered repeatedly','as the name of a bird’s nest','to mean a newly baked loaf'],'figuratively, for something considered repeatedly','Chewing cud can be extended metaphorically to repeated thought.') ]});
D('culinary',{etymology:E('culinary comes from Latin culinarius, “of the kitchen,” from culina “kitchen”; the adjective concerns cooking or food preparation.','culinary'),contexts:[C('culinary.s1','烹饪课程','The culinary school requires first-year students to practice knife skills and prepare a balanced meal before they work in a restaurant kitchen.','这所烹饪学校要求一年级学生练习刀工并做出一顿营养均衡的饭菜，然后才能进入餐馆厨房实习。','The culinary school requires first-year students / to practice knife skills and prepare a balanced meal / before they work in a restaurant kitchen.','culinary 作定语，修饰 school，表示该校以烹饪为专门领域。','课程教授烹饪技能，符合“烹饪的”义 s1。')],mistakes:[M('The culinary lesson taught students to repair a bicycle chain and adjust its brakes.','The mechanical lesson taught students to repair a bicycle chain and adjust its brakes.','修车技能不属于烹饪领域；culinary 应用于厨房或食物制作。')],quiz:[Q('culinary',1,1,'A culinary tradition concerns?',['cooking and food','the motion of planets','the design of road bridges'],'cooking and food','Culinary relates to cooking or the kitchen.'),Q('culinary',2,1,'Which book is most likely a culinary reference?',['a guide to regional soups and cooking methods','a handbook on stellar navigation','a manual for repairing elevators'],'a guide to regional soups and cooking methods','Recipes and cooking methods are culinary subjects.'),Q('culinary',3,1,'A culinary student is likely learning to?',['prepare and serve food professionally','survey underground tunnels','translate ancient inscriptions'],'prepare and serve food professionally','Culinary training focuses on food preparation.'),Q('culinary',4,1,'Choose the phrase that uses culinary naturally.',['culinary techniques','culinary longitude of Mars','culinary bicycle tyre'],'culinary techniques','Cooking techniques are naturally described as culinary.') ]});
D('culmination',{etymology:E('culmination derives from Latin culminare “to crown or reach a summit,” from culmen “top”; English uses it for a highest point or final result.','culmination'),contexts:[C('culmination.s1','戏剧高潮','The final argument was the dramatic culmination of the play, bringing together clues that had seemed unrelated in the opening scene.','最后一场辩论是这部戏剧的高潮，把开场时看似互不相关的线索汇集到一起。','The final argument was the dramatic culmination of the play / bringing together clues / that had seemed unrelated in the opening scene.','culmination 作可数名词，常用 the culmination of + 过程/作品。','全剧线索在结尾汇合，达到戏剧顶点，符合 s1。'),C('culmination.s2','长期工程','The bridge was the culmination of five years of planning, surveying, and construction by engineers from three towns.','这座桥是三个城镇的工程师经过五年规划、测绘和施工后取得的最终成果。','The bridge was the culmination of five years of planning / surveying and construction / by engineers from three towns.','culmination of 后接一系列努力，表示其最终成果。','桥梁作为多年工程的产出，体现结果义 s2。')],mistakes:[M('The culmination of the expedition was its first step out of the village, before the journey began.','The beginning of the expedition was its first step out of the village, before the journey began.','旅程开端不能叫作达到顶点或最终成果的 culmination。','word-formation')],quiz:[Q('culmination',1,1,'The culmination of a long campaign is its?',['highest or climactic point','first unnoticed planning meeting','temporary pause halfway through'],'highest or climactic point','Culmination can denote the climax or highest point.'),Q('culmination',2,2,'A new clinic is the culmination of years of fundraising. The clinic is?',['the final result of that effort','the first donation ever made','unrelated to the fundraising'],'the final result of that effort','The second sense emphasizes the outcome of a long process.'),Q('culmination',3,1,'Which event is most likely the culmination of a mystery play?',['the scene where the clues finally reveal the culprit','the actors’ first rehearsal','the interval before the second act'],'the scene where the clues finally reveal the culprit','The revelation serves as the dramatic climax.'),Q('culmination',4,2,'Choose the natural construction.',['the culmination of years of research','the culmination before any work begins','the culmination of a process that produces no result'],'the culmination of years of research','The phrase identifies an outcome reached after sustained effort.') ]});
D('culpable',{etymology:E('culpable came through French culpable from Latin culpabilis, “blameworthy,” from culpa “fault”; it describes someone or something deserving blame.','culpable'),contexts:[C('culpable.s1','事故调查','The inquiry found the contractor culpable for ignoring the cracked support, although the report also noted that the inspector had missed earlier warnings.','调查认定承包商因忽视支架裂缝而应受责备，尽管报告也指出检查员此前漏掉了警告。','The inquiry found the contractor culpable for ignoring the cracked support / although the report also noted / that the inspector had missed earlier warnings.','find + 人 + culpable for + 行为，表示认定其应对此负责。','承包商忽视危险支架，存在可归责行为，符合 s1。'),C('culpable.s2','司法判责','The judge declared the driver culpable in the fatal collision after the evidence showed he had deliberately disabled the warning system.','证据显示司机故意关闭警报系统后，法官认定他在致命碰撞中有罪责。','The judge declared the driver culpable in the fatal collision / after the evidence showed / he had deliberately disabled the warning system.','culpable in an offense/collision 表示对此违法或有害事件负罪责。','故意关闭安全系统后造成致命事故，支持法律上的有罪责义 s2。')],mistakes:[M('The review found the employee culpable, but also established that she had followed every safety rule and had no role in the failure.','The review found the employee blameless, because she had followed every safety rule and had no role in the failure.','既无违规也无因果责任的员工不应被称为 culpable。')],quiz:[Q('culpable',1,1,'Someone culpable for a mistake is?',['deserving blame for it','completely unaware that it happened','praised for preventing it'],'deserving blame for it','Culpable means blameworthy or responsible for wrongdoing.'),Q('culpable',2,2,'A jury finds a driver culpable in a crime. It has found the driver?',['responsible for the offense','innocent of every charge','a witness who had no involvement'],'responsible for the offense','In legal contexts, culpable means bearing guilt or responsibility.'),Q('culpable',3,1,'Which evidence supports calling a manager culpable?',['The manager knowingly ignored a required safety check.','The manager was absent and had no authority over the check.','The check passed and no rule was broken.'],'The manager knowingly ignored a required safety check.','Knowing disregard of a duty can make the manager blameworthy.'),Q('culpable',4,2,'Choose the closest contrast to culpable.',['blameless','liable','at fault'],'blameless','Blameless is the opposite of deserving blame.') ]});
D('culprit',{etymology:E('culprit is recorded in English legal usage by the seventeenth century, apparently from a courtroom formula; its ultimate derivation is uncertain. It names a wrongdoer or cause of trouble.','culprit'),contexts:[C('culprit.s1','案件调查','Security footage showed the culprit entering the archive after closing and carrying the missing ledger under his coat.','监控录像显示，罪犯打烊后进入档案室，把丢失的账簿藏在外套下面带走。','Security footage showed the culprit entering the archive after closing / and carrying the missing ledger / under his coat.','culprit 作可数名词，指实施不法行为的人。','录像中的人偷走账簿，符合“罪犯”义 s1。'),C('culprit.s2','设备故障','When the heater failed, a clogged filter turned out to be the culprit, restricting the airflow throughout the flat.','暖气故障后，堵塞的滤网被发现是问题根源，限制了整套公寓的气流。','When the heater failed / a clogged filter turned out to be the culprit / restricting the airflow throughout the flat.','culprit 可比喻导致问题的事物；turn out to be 后接原因。','堵塞滤网导致暖气故障，体现原因义 s2。')],mistakes:[M('The mechanic called the culprit when he found the blocked filter that caused the engine to overheat.','The mechanic identified the culprit when he found the blocked filter that caused the engine to overheat.','culprit 是名词，不能直接当作及物动词用；应说 identify/find the culprit。','grammar')],quiz:[Q('culprit',1,1,'In a burglary report, the culprit is?',['the person who committed the crime','the officer who arrived later','the owner whose property was taken'],'the person who committed the crime','Culprit can mean the wrongdoer responsible for an offense.'),Q('culprit',2,2,'The investigation found a faulty valve was the culprit. The valve was?',['the cause of the problem','the person arrested for theft','a witness who saw the fault'],'the cause of the problem','Culprit is also used figuratively for the source of trouble.'),Q('culprit',3,1,'Which sentence uses culprit for a person?',['The culprit confessed to taking the painting.','A worn belt was the culprit behind the squeal.','Dust was the culprit in the jammed printer.'],'The culprit confessed to taking the painting.','The subject is a person who committed the offense.'),Q('culprit',4,2,'Choose the figurative use.',['The leaking seal was the culprit behind the rising water bill.','The suspect was convicted as the culprit.','The witness named the culprit in court.'],'The leaking seal was the culprit behind the rising water bill.','A mechanical cause is figuratively described as the culprit.') ]});
D('cultivated',{etymology:E('cultivated is the past participle and adjective from cultivate, through French from Latin cultivare “prepare land for crops”; it also describes a refined or developed quality.','cultivated'),contexts:[C('cultivated.s1','农业生产','The cultivated hillside produced olives after workers terraced the slope and planted rows that could be irrigated safely.','工人把山坡修成梯田并种下可安全灌溉的行列后，耕种过的山地结出了橄榄。','The cultivated hillside produced olives / after workers terraced the slope / and planted rows that could be irrigated safely.','cultivated 作定语形容词，表示土地已被耕种或利用。','种植并灌溉的山坡属于耕种地，符合 s1。'),C('cultivated.s2','个人修养','Despite her cultivated manner, the pianist spoke warmly to nervous beginners and never made them feel ignorant.','尽管举止有教养，这位钢琴家仍亲切地与紧张的初学者交谈，从不让他们觉得自己无知。','Despite her cultivated manner / the pianist spoke warmly to nervous beginners / and never made them feel ignorant.','cultivated 修饰 manner，表示经过培养而有教养、文雅。','温文且有礼的举止体现涵养义 s2。')],mistakes:[M('The cultivated field had never been plowed, planted, or tended, and was still untouched wilderness.','The uncultivated field had never been plowed, planted, or tended, and was still untouched wilderness.','从未耕作的土地应为 uncultivated；cultivated 意为耕种过的。','word-formation')],quiz:[Q('cultivated',1,1,'A cultivated plot of land has usually been?',['prepared and used for growing crops','sealed under concrete since it formed','left entirely wild and untended'],'prepared and used for growing crops','The agricultural sense means tilled or farmed.'),Q('cultivated',2,2,'A cultivated speaker is likely to be?',['educated and refined in manner','unable to understand any topic','physically grown in a field'],'educated and refined in manner','The figurative sense refers to refinement developed through learning.'),Q('cultivated',3,1,'Which is the literal use of cultivated?',['cultivated soil ready for planting','cultivated taste in classical music','cultivated manners at dinner'],'cultivated soil ready for planting','Soil prepared for crops demonstrates the agricultural sense.'),Q('cultivated',4,2,'Her cultivated taste in art suggests that she?',['has developed informed appreciation','has grown a painting in a garden','has never seen an artwork'],'has developed informed appreciation','A cultivated taste is refined through exposure and learning.') ]});
D('cultivation',{etymology:E('cultivation is formed from cultivate plus -ation; cultivate came through French from Latin cultivare, associated with preparing and tending land.','cultivation'),contexts:[C('cultivation.s1','茶园种植','Tea cultivation on the steep hillside depends on careful pruning, steady rainfall, and workers who can reach each narrow terrace.','陡峭山坡上的茶叶种植依靠细致修剪、稳定降雨，以及能够到达每一层狭窄梯田的工人。','Tea cultivation on the steep hillside / depends on careful pruning / steady rainfall / and workers who can reach each narrow terrace.','cultivation 作不可数名词，后接作物表示种植、栽培活动。','修剪和采摘茶树属于农作物栽培，符合 s1。'),C('cultivation.s2','能力培养','The cultivation of patience helped the apprentice continue practicing difficult passages without rushing through mistakes.','耐心的培养帮助这名学徒继续练习困难段落，而不因失误就急于跳过。','The cultivation of patience helped the apprentice / continue practicing difficult passages / without rushing through mistakes.','cultivation of + 抽象品质表示逐渐培养、发展该品质。','耐心通过练习逐渐养成，对应教化/培养义 s2。')],mistakes:[M('The cultivation of patience meant refusing to practice or develop patience in any way.','The neglect of patience meant refusing to practice or develop patience in any way.','cultivation 是培育、发展；完全不培养应称 neglect。','word-formation')],quiz:[Q('cultivation',1,1,'Cultivation of rice refers to?',['growing and tending rice','selling a finished house','measuring the height of a mountain'],'growing and tending rice','The agricultural sense is the practice of growing crops.'),Q('cultivation',2,2,'The cultivation of curiosity in children involves?',['encouraging that quality to develop','preventing all questions','planting a child in soil'],'encouraging that quality to develop','The figurative sense means fostering a personal quality.'),Q('cultivation',3,1,'Which activity belongs to land cultivation?',['preparing beds and tending seedlings','reading a poem at a concert','repairing a clock’s spring'],'preparing beds and tending seedlings','These are practical steps in growing plants.'),Q('cultivation',4,2,'Choose a natural abstract use.',['the cultivation of good judgment','the cultivation of a forgotten street sign','the cultivation of yesterday’s weather'],'the cultivation of good judgment','Judgment can be developed through experience and learning.') ]});
D('culturally',{etymology:E('culturally is formed from cultural, from culture (via French from Latin cultura “cultivation”), plus the adverb suffix -ly; it means in cultural terms or with respect to culture.','culturally'),contexts:[C('culturally.s1','跨文化教育','The recipe is culturally important to the community, so the museum invited local cooks to explain when the dish is served and why.','这道食谱对当地社群具有重要的文化意义，因此博物馆邀请本地厨师说明它何时上桌以及背后的原因。','The recipe is culturally important to the community / so the museum invited local cooks / to explain when the dish is served and why.','culturally 修饰形容词 important，限定“重要”的文化维度。','菜肴与社群传统及意义相关，体现文化层面的重要性。')],mistakes:[M('The festival was culturally significant because the guests measured its importance only by the amount of rainfall.','The festival was culturally significant because it expressed the community’s traditions and shared identity.','仅以降雨量衡量与文化意义无关；此处应说明传统、价值或社群生活。')],quiz:[Q('culturally',1,1,'A culturally important ceremony matters chiefly because of its?',['role in a community’s traditions and meanings','temperature in degrees','distance from the nearest highway'],'role in a community’s traditions and meanings','Culturally marks the dimension of customs, values, and shared life.'),Q('culturally',2,1,'A city is culturally diverse when it?',['contains communities with varied cultural traditions','has only one kind of building material','is colder than neighboring cities'],'contains communities with varied cultural traditions','Cultural diversity concerns different traditions and communities.'),Q('culturally',3,1,'In “culturally adapted,” culturally tells us the adaptation is?',['made with attention to cultural context','done only in a chemistry lab','a measurement of physical height'],'made with attention to cultural context','The adverb specifies adaptation to cultural context.'),Q('culturally',4,1,'Choose the natural use of culturally.',['The custom is culturally specific to the region.','The custom is culturally three metres long.','The custom is culturally yesterday.'],'The custom is culturally specific to the region.','Culturally modifies an adjective describing cultural context.') ]});
D('cumbersome',{etymology:E('cumbersome is recorded in English from the sixteenth century, formed from cumber “burden or hamper” plus -some “tending to”; it means awkwardly heavy or inconvenient.','cumbersome'),contexts:[C('cumbersome.s1','行李搬运','The cumbersome trunk barely fit through the train door, and two porters had to lift its iron-bound corners together.','这只笨重的大箱子勉强通过火车门，两名搬运工不得不一起抬起包着铁角的箱子。','The cumbersome trunk barely fit through the train door / and two porters had to lift / its iron-bound corners together.','cumbersome 作定语形容词，形容体积或重量带来的搬运困难。','大且沉、需两人抬的行李符合笨重义 s1。'),C('cumbersome.s2','手续流程','The reimbursement process was cumbersome, requiring employees to print six forms and obtain signatures from three departments.','报销流程很繁琐，员工必须打印六张表格并取得三个部门的签字。','The reimbursement process was cumbersome / requiring employees to print six forms / and obtain signatures from three departments.','cumbersome 描述流程时表示复杂麻烦、不便操作。','多张表格和多部门签字使流程难办，符合 s2。')],mistakes:[M('The lightweight folding stool was cumbersome to carry because it weighed only a few grams and fit in a pocket.','The lightweight folding stool was convenient to carry because it weighed only a few grams and fit in a pocket.','轻巧易携的物品不符合笨重或难处理的 cumbersome 含义。')],quiz:[Q('cumbersome',1,1,'A cumbersome suitcase is difficult to carry because it is?',['awkwardly large or heavy','small and effortless to handle','made of air'],'awkwardly large or heavy','The physical sense concerns awkward weight or bulk.'),Q('cumbersome',2,2,'A cumbersome approval system is?',['unnecessarily complicated and inconvenient','fast and simple to use','a machine for carrying luggage'],'unnecessarily complicated and inconvenient','The figurative sense describes a difficult, inefficient process.'),Q('cumbersome',3,1,'Which item is most likely cumbersome?',['a massive stone table moved by four people','a folded map in a pocket','a light pencil carried behind an ear'],'a massive stone table moved by four people','Its size and weight make the table awkward to move.'),Q('cumbersome',4,2,'Replacing ten paper forms with one clear online form makes a process less?',['cumbersome','culinary','crystalline'],'cumbersome','Fewer steps and simpler handling reduce inconvenience.') ]});
D('cuneiform',{etymology:E('cuneiform combines Latin cuneus “wedge” and forma “shape”; the name describes the wedge-shaped marks used in ancient writing systems.','cuneiform'),contexts:[C('cuneiform.s1','古代文字','The archaeologist photographed a clay tablet covered in cuneiform, whose wedge-shaped impressions recorded a merchant’s grain accounts.','考古学家拍下了一块刻满楔形文字的泥板，上面的楔形印痕记录了一名商人的谷物账目。','The archaeologist photographed a clay tablet / covered in cuneiform / whose wedge-shaped impressions recorded a merchant’s grain accounts.','cuneiform 作不可数名词，指楔形文字书写系统。','泥板上的楔形印记构成古代文字记录，符合 s1。'),C('cuneiform.s2','形状描述','Under magnification, the fossil showed a cuneiform fragment, broad at one end and narrowing like a wedge.','放大观察时，化石呈现出一块楔形碎片，一端较宽，另一端像楔子一样收窄。','Under magnification / the fossil showed a cuneiform fragment / broad at one end / and narrowing like a wedge.','cuneiform 作形容词，修饰 fragment，表示楔形的。','一端宽、一端窄的楔状外形体现形状义 s2。')],mistakes:[M('The tablet’s cuneiform consisted of smooth round letters with no wedge-shaped strokes.','The tablet’s alphabetic script consisted of smooth round letters with no wedge-shaped strokes.','没有楔形笔画的圆体字不符合 cuneiform 的命名及典型外观。')],quiz:[Q('cuneiform',1,1,'Cuneiform writing is named for its?',['wedge-shaped marks','circular holes','colorful ink'],'wedge-shaped marks','Cuneiform literally refers to wedge-shaped forms.'),Q('cuneiform',2,2,'A cuneiform shard has a shape that is?',['wedge-like','perfectly spherical','flat as a line'],'wedge-like','As an adjective, cuneiform can describe wedge-shaped objects.'),Q('cuneiform',3,1,'An ancient clay tablet covered in cuneiform most likely contains?',['impressed wedge-like signs','printed modern barcodes','musical notes carved in a circle'],'impressed wedge-like signs','Ancient cuneiform was written by pressing wedge-shaped marks into clay.'),Q('cuneiform',4,2,'The surgeon described the bone as cuneiform. The description refers to its?',['wedge-shaped form','language of inscription','age in years'],'wedge-shaped form','The adjective can describe an anatomical wedge-shaped bone.') ]});
D('curable',{etymology:E('curable is formed from cure, through French and Latin cura “care or treatment,” plus -able “capable of”; it means capable of being cured.','curable'),contexts:[C('curable.s1','医疗咨询','The specialist explained that the infection was curable with a full course of antibiotics, although the patient still needed follow-up tests.','专科医生解释说，这种感染可以通过完整疗程的抗生素治愈，不过患者仍需复查。','The specialist explained that the infection was curable / with a full course of antibiotics / although the patient still needed follow-up tests.','curable 作表语形容词，说明疾病可以治愈；with 短语指出治疗方法。','抗生素能消除感染，符合可医治义 s1。')],mistakes:[M('The infection was curable, but every available treatment had failed and doctors agreed it could never be cured.','The infection was incurable, because every available treatment had failed and doctors agreed it could never be cured.','明确无法治愈的疾病应称 incurable；curable 表示能够治疗至康复。','word-formation')],quiz:[Q('curable',1,1,'A curable condition is one that?',['can be successfully treated','cannot improve under any treatment','is a cure used by doctors'],'can be successfully treated','-able means capable of being cured in this adjective.'),Q('curable',2,1,'The doctor says the disease is curable. What does that imply?',['a treatment can eliminate or resolve it','it must be inherited by every patient','no treatment should be attempted'],'a treatment can eliminate or resolve it','Curable means capable of being cured.'),Q('curable',3,1,'Which sentence uses curable correctly?',['The infection was curable with prompt treatment.','The cure was curable the patient carefully.','The curable was prescribed at noon.'],'The infection was curable with prompt treatment.','The adjective describes a disease or condition that can be cured.'),Q('curable',4,1,'What is the closest opposite of curable?',['incurable','treatable','recoverable'],'incurable','The prefix in- reverses the meaning: incurable cannot be cured.') ]});
D('curative',{etymology:E('curative derives from Latin curare “to care for or heal,” from cura “care”; the adjective means having healing power, while the noun refers to a remedy.','curative'),contexts:[C('curative.s1','疗效描述','The physician regarded the new treatment as curative because follow-up scans showed that the infection had been eliminated.','医生认为新疗法具有治愈作用，因为复查扫描显示感染已经清除。','The physician regarded the new treatment as curative / because follow-up scans showed / that the infection had been eliminated.','curative 作表语形容词，描述治疗具有治愈疾病的效果。','复查确认感染清除，支持“能治愈的”义 s1。'),C('curative.s2','药物名词','In the old village account, a curative made from willow bark was given to travelers with aching joints.','在旧村志中，旅人关节疼痛时会服用一种用柳树皮制成的药物。','In the old village account / a curative made from willow bark / was given to travelers / with aching joints.','curative 可作可数名词，指用于治疗的药物或疗法。','由树皮制成并用于治疗疼痛的制剂，符合名词义 s2。')],mistakes:[M('The curative was a decorative ribbon that no one used to treat an illness.','The curative was a medicinal preparation that people used to treat an illness.','curative 作名词指治疗方法或药剂；纯装饰物不具有治疗用途。')],quiz:[Q('curative',1,1,'A curative treatment is intended to?',['heal the disease','make no difference to health','measure a patient’s height'],'heal the disease','The adjective means able to cure or heal.'),Q('curative',2,2,'An herbal curative in a historical account is?',['a remedy or medicinal preparation','a person who guards a museum','a type of kitchen utensil'],'a remedy or medicinal preparation','As a noun, curative can refer to a treatment or remedy.'),Q('curative',3,1,'Which result best supports calling a therapy curative?',['The illness is eliminated after treatment.','The patient learns the drug’s color.','Symptoms remain unchanged forever.'],'The illness is eliminated after treatment.','A curative therapy heals the condition rather than merely describing it.'),Q('curative',4,2,'Choose the noun use of curative.',['The healer prepared a curative from local herbs.','The curative method was carefully tested.','Doctors hoped for a curative effect.'],'The healer prepared a curative from local herbs.','Here a curative is a thing prepared as a remedy.') ]});
D('curator',{etymology:E('curator came from Latin curator “overseer,” from curare “to care for”; the modern title names a person who cares for and organizes a collection.','curator'),contexts:[C('curator.s1','博物馆工作','The curator selected ship logs and navigation tools for the new exhibition, then wrote labels explaining how each object was used.','策展人为新展览挑选航海日志和导航工具，随后撰写标签说明每件物品的用途。','The curator selected ship logs and navigation tools / for the new exhibition / then wrote labels / explaining how each object was used.','curator 作可数名词，指负责馆藏或展览的专业人员。','他挑选展品并撰写说明，体现馆藏管理与策展职责。')],mistakes:[M('The curator preserved the gallery’s collection by selling every object and keeping no record of them.','The curator preserved the gallery’s collection by cataloguing and caring for its objects.','不留藏品、不作记录与 curator 的照管和管理职责相反。')],quiz:[Q('curator',1,1,'A museum curator is primarily responsible for?',['caring for collections and organizing exhibitions','repairing every visitor’s car','writing laws for the city council'],'caring for collections and organizing exhibitions','Curators manage collections and often plan exhibitions.'),Q('curator',2,1,'Which task most clearly belongs to a curator?',['choosing artifacts and preparing exhibit labels','selling train tickets at the station','mixing concrete at a construction site'],'choosing artifacts and preparing exhibit labels','Selection and interpretation of objects are curatorial tasks.'),Q('curator',3,1,'The curator inspected a painting’s condition. This most likely concerned?',['preservation of a collection item','the museum café menu','traffic outside the museum'],'preservation of a collection item','A curator helps care for and document collection objects.'),Q('curator',4,1,'A curator’s work usually involves?',['specialized responsibility for a collection','custodial care of a private child only','curing visitors of illness'],'specialized responsibility for a collection','The word denotes a person entrusted with a collection or its interpretation.') ]});
D('cure-all',{etymology:E('cure-all is an English compound of cure and all, first used for a supposed remedy able to cure every illness; it is also figurative for a universal solution.','cure-all'),contexts:[C('cure-all.s1','民间疗法','The travelling seller advertised his tonic as a cure-all, promising relief from everything from headaches to aching joints.','巡回商贩把他的滋补剂吹成包治百病的灵药，声称头痛到关节酸痛都能缓解。','The travelling seller advertised his tonic as a cure-all / promising relief from everything / from headaches to aching joints.','cure-all 作可数复合名词，指声称能治所有疾病的药物。','广告夸称一种药能应对多种疾病，符合药物义 s1。')],mistakes:[M('The tested antibiotic was a cure-all because doctors had established that it treats only one specific bacterial infection.','The tested antibiotic was a targeted treatment because doctors had established that it treats only one specific bacterial infection.','仅对一种特定感染有效的药不是“万灵药”；cure-all 暗含普遍包治的夸称。')],quiz:[Q('cure-all',1,1,'A cure-all is traditionally claimed to?',['treat every illness','cause one specific symptom','measure medicine accurately'],'treat every illness','The compound names a supposed universal remedy.'),Q('cure-all',2,1,'Why might a doctor distrust an advertised cure-all?',['No single remedy is established as curing every condition.','The word all means “none.”','A cure-all is a kind of measuring cup.'],'No single remedy is established as curing every condition.','The term often signals an exaggerated universal medical claim.'),Q('cure-all',3,1,'“There is no cure-all for loneliness” means?',['no single solution fixes every case','a universal medicine is available','loneliness is an infectious disease'],'no single solution fixes every case','The noun is extended figuratively to a universal solution.'),Q('cure-all',4,1,'Choose the sentence using cure-all figuratively.',['The new app is no cure-all for every school problem.','The cure-all prescribed a cure-alling tablet.','The cure-all is a measure of all illnesses.'],'The new app is no cure-all for every school problem.','Here it means a supposed universal fix, not an actual drug.') ]});
D('curio',{etymology:E('curio is a shortened form of curiosity, used since the nineteenth century for a curious or unusual object collected for interest.','curio'),contexts:[C('curio.s1','古董商店','Among the maps and brass instruments, the shop displayed a tiny carved curio shaped like a bird with two beaks.','在地图和黄铜仪器之间，店里陈列着一件小巧的雕刻珍玩，形状像一只有两个喙的鸟。','Among the maps and brass instruments / the shop displayed a tiny carved curio / shaped like a bird with two beaks.','curio 作可数名词，指因奇特或有趣而收藏的小物件。','造型罕见的雕刻品作为收藏陈列，符合 s1。')],mistakes:[M('The warehouse called a mass-produced plain cardboard box a curio, although it was ordinary and of no collecting interest.','The warehouse called a rare carved box a curio because collectors valued its unusual design.','普通量产纸箱没有稀奇或收藏价值，不符合 curio 的含义。')],quiz:[Q('curio',1,1,'A curio in an antique shop is likely to be?',['an unusual object kept for interest','a standard shipping invoice','a large field used for crops'],'an unusual object kept for interest','Curio refers to a curious or collectible object.'),Q('curio',2,1,'Which item might a collector call a curio?',['a tiny clockwork fish with an odd design','a stack of identical blank envelopes','a routine utility bill'],'a tiny clockwork fish with an odd design','Its unusual design makes it an interesting small object.'),Q('curio',3,1,'The word curio is historically shortened from?',['curiosity','custodian','cucumber'],'curiosity','Curio developed as a shortened form of curiosity.'),Q('curio',4,1,'Choose a natural use.',['The museum shop sold a carved wooden curio.','The curio watered the field for two hours.','She curioed the package shut.'],'The museum shop sold a carved wooden curio.','A curio is a collectible object, often unusual or decorative.') ]});
D('curiously',{etymology:E('curiously is formed from curious, from Latin curiosus “careful or inquisitive,” plus -ly; it means with curiosity or, as a sentence adverb, strangely.','curiously'),contexts:[C('curiously.s1','科学观察','The child curiously lifted the shell to see whether a small crab had hidden beneath it.','孩子好奇地掀起贝壳，想看看下面是不是藏着一只小螃蟹。','The child curiously lifted the shell / to see whether a small crab / had hidden beneath it.','curiously 修饰 lifted，说明动作出于好奇。','孩子想探查贝壳下的情况，体现好奇地做某事 s1。'),C('curiously.s2','反常现象','Curiously, the two clocks stopped at exactly the same minute, even though they used different batteries.','奇怪的是，这两只钟停在完全相同的分钟，尽管它们使用不同的电池。','Curiously / the two clocks stopped at exactly the same minute / even though they used different batteries.','句首 curiously 是评注性副词，表达说话人觉得事情奇怪。','两只独立的钟同时停走显得反常，对应“奇怪的是”义 s2。')],mistakes:[M('Curiously, the child inspected the unfamiliar shell because she was utterly uninterested in what might be inside.','The child inspected the unfamiliar shell out of curiosity because she wanted to know what might be inside.','curiously 表示出于好奇；明确毫无兴趣与此原因不一致。')],quiz:[Q('curiously',1,1,'He curiously opened the box. He did so?',['because he wanted to know what was inside','because he already knew every detail','without looking at the box'],'because he wanted to know what was inside','The adverb can describe an inquisitive action.'),Q('curiously',2,2,'“Curiously, no one remembered the meeting” signals that the fact is?',['strange or unexpected','a question asked with great volume','a carefully measured distance'],'strange or unexpected','As a sentence adverb, curiously comments that something is odd.'),Q('curiously',3,1,'Which sentence uses the inquisitive sense?',['The child curiously examined the fossil.','Curiously, the fossil vanished overnight.','The fossil was curiously shaped, with an unusual curve.'],'The child curiously examined the fossil.','Here curiously describes the child’s manner and interest.'),Q('curiously',4,2,'Choose the sentence-adverb use.',['Curiously, both keys opened the same lock.','She curiously studied every label.','The dog sniffed curiously at the bag.'],'Curiously, both keys opened the same lock.','The opening adverb comments on the surprising coincidence.') ]});
D('curly',{etymology:E('curly is formed from curl plus the adjective suffix -y; curl entered English through French, while the word’s deeper origin is uncertain.','curly'),contexts:[C('curly.s1','发型描写','Her curly hair sprang back into tight loops after the rain, so she tied it up before entering the laboratory.','她的卷发淋雨后又弹回紧密的小卷，因此进入实验室前把头发扎了起来。','Her curly hair sprang back into tight loops after the rain / so she tied it up / before entering the laboratory.','curly 作定语形容词，描述头发弯成卷状。','雨后发丝回卷成环，符合卷曲义 s1。'),C('curly.s2','动物外貌','The lamb had a curly coat of soft fleece, with small ringlets along its back and neck.','这只小羊长着卷曲柔软的羊毛，背部和颈部排列着一圈圈小卷。','The lamb had a curly coat of soft fleece / with small ringlets / along its back and neck.','curly 修饰 coat，表示毛发或外层呈卷曲状。','绵羊毛形成小卷，对应卷毛义 s2。')],mistakes:[M('The stylist described the hair as curly because each strand formed a perfectly straight line with no bends.','The stylist described the hair as straight because each strand formed a line with no bends.','没有弯曲或卷环的头发是 straight，不是 curly。')],quiz:[Q('curly',1,1,'Curly hair is hair that?',['forms bends, loops, or curls','falls in perfectly straight strands','has been cut extremely short'],'forms bends, loops, or curls','Curly describes hair with a naturally curled shape.'),Q('curly',2,2,'A sheep with a curly fleece has?',['wool growing in small curls','a smooth metal covering','no coat at all'],'wool growing in small curls','The adjective also describes curled animal hair or fleece.'),Q('curly',3,1,'Which object is most naturally described as curly?',['a spring-shaped lock of hair','a ruler edge with no bends','a flat sheet of glass'],'a spring-shaped lock of hair','A lock coiled into bends is curly.'),Q('curly',4,2,'“A curly-haired lamb” means the lamb has?',['a coat with curled wool','a diet made entirely of curls','a straight, hairless body'],'a coat with curled wool','The adjective modifies the animal’s hair or fleece.') ]});
D('currier',{etymology:E('currier is the agent noun from curry in the leatherworking sense, ultimately from French corroyer “prepare or dress leather”; it names a worker who finishes hides.','currier'),contexts:[C('currier.s1','皮革工艺','The currier softened the tanned hide with oils and worked its surface until it was flexible enough for a saddle.','制革匠用油脂软化鞣过的兽皮，并反复处理表面，直到它柔韧到足以制作马鞍。','The currier softened the tanned hide with oils / and worked its surface / until it was flexible enough for a saddle.','currier 作职业名词，指对已鞣皮革进行整理和加工的人。','软化与整理皮革表面是制革匠的工作。')],mistakes:[M('The currier finished the leather by turning the hide into a fresh vegetable harvest.','The currier finished the leather by softening and dressing the hide for use.','currier 是皮革加工者，不能指收割蔬菜的农人。')],quiz:[Q('currier',1,1,'A currier traditionally works with?',['leather hides','curried rice','museum paintings'],'leather hides','A currier dresses and finishes leather.'),Q('currier',2,1,'Which task might a currier perform?',['softening and finishing a tanned hide','raising a curry sauce to a boil','curating a botanical garden'],'softening and finishing a tanned hide','Finishing and conditioning leather is the currier’s trade.'),Q('currier',3,1,'The suffix-like ending in currier identifies a?',['person whose trade is preparing leather','container used to hold curry','tool for measuring curvature'],'person whose trade is preparing leather','Currier is an occupational agent noun.'),Q('currier',4,1,'Choose the sentence in which currier is used correctly.',['The currier treated the hide before it was made into boots.','The currier served bowls of rice at dinner.','The currier calculated the curve of the road.'],'The currier treated the hide before it was made into boots.','The leatherworker prepares hides for later use.') ]});
D('curry',{etymology:E('curry meaning a spiced dish reached English through Portuguese and Anglo-Indian usage, ultimately associated with Tamil kari “sauce or relish”; the verb means season with curry spices.','curry'),contexts:[C('curry.s1','餐饮点单','The café’s vegetable curry simmered with chickpeas and spinach, and the cook served it over rice with a wedge of lime.','咖啡馆的蔬菜咖喱加入鹰嘴豆和菠菜炖煮，厨师把它浇在米饭上并配了一角青柠。','The café’s vegetable curry simmered with chickpeas and spinach / and the cook served it over rice / with a wedge of lime.','curry 作可数名词，指一道以咖喱香料调味的菜。','炖菜含咖喱调味并配饭，符合菜肴义 s1。'),C('curry.s2','烹调动作','Before roasting the vegetables, the cook curried them with turmeric, cumin, and ground coriander.','烘烤蔬菜前，厨师用姜黄、孜然和芫荽粉给它们调上咖喱风味。','Before roasting the vegetables / the cook curried them with turmeric / cumin / and ground coriander.','curry 作及物动词，意为用咖喱调味；过去式 curried。','所列香料用于增加咖喱风味，体现动词义 s2。')],mistakes:[M('The cook curried the vegetables by washing away every spice and leaving them completely unseasoned.','The cook rinsed the vegetables, then curried them with a blend of spices.','完全去除香料而不调味不是 curry 的“用咖喱调味”义。')],quiz:[Q('curry',1,1,'A bowl of curry is usually?',['a dish seasoned with a curry spice mixture','a dessert made only from ice','a type of leatherworker'],'a dish seasoned with a curry spice mixture','Curry as a noun names a spiced dish.'),Q('curry',2,2,'To curry the vegetables means to?',['season them with curry spices','remove all flavoring from them','freeze them before serving'],'season them with curry spices','The verb means to prepare or flavor with curry.'),Q('curry',3,1,'Which phrase uses curry as a noun?',['a lentil curry with rice','to curry the potatoes','curried vegetables'],'a lentil curry with rice','Here curry names the prepared food.'),Q('curry',4,2,'The chef curried the sauce before serving it. The chef?',['added curry seasoning','served leather to the guests','measured the sauce’s curvature'],'added curry seasoning','Curry is a transitive verb in this sentence.') ]});
D('curtsy',{etymology:E('curtsy is a variant spelling of courtesy, altered through association with the curtsy gesture; it names a respectful bending of the knees and also the act of performing it.','curtsy'),contexts:[C('curtsy.s1','礼仪动作','At the end of the performance, the young dancer gave a curtsy to the audience before joining the rest of the cast.','演出结束时，小舞者向观众行了屈膝礼，然后回到其他演员身边。','At the end of the performance / the young dancer gave a curtsy to the audience / before joining the rest of the cast.','give a curtsy 是名词搭配，表示行屈膝礼。','舞者向观众屈膝致意，符合礼仪动作 s1。'),C('curtsy.s2','王室礼节','The visitor curtsied when she was introduced to the queen, lowering her body briefly before standing upright again.','来访者被介绍给女王时行了屈膝礼，短暂下蹲后又站直。','The visitor curtsied when she was introduced to the queen / lowering her body briefly / before standing upright again.','curtsy 作不及物动词，过去式 curtsied，描述行礼动作。','短暂屈膝后起身，是动词义 s2。')],mistakes:[M('She gave a curtsy by bowing her head while keeping both knees locked and her body upright.','She gave a curtsy by bending her knees and lowering her body briefly.','仅低头且膝盖不弯不是 curtsy；该礼动作的关键是屈膝。')],quiz:[Q('curtsy',1,1,'A curtsy is a gesture in which someone?',['bends the knees and lowers the body briefly','raises both arms to signal a plane','kneels to repair a floor'],'bends the knees and lowers the body briefly','The noun names a formal bending of the knees as a greeting or respect.'),Q('curtsy',2,2,'She curtsied to the guest. What did she do?',['performed a brief knee-bending gesture','served the guest a curry','measured the room’s curve'],'performed a brief knee-bending gesture','Curtsy as a verb means to make the curtsy gesture.'),Q('curtsy',3,1,'Which sentence uses curtsy as a noun?',['The child gave a curtsy after the dance.','The child curtsied after the dance.','The child bowed her head after the dance.'],'The child gave a curtsy after the dance.','The phrase “a curtsy” uses the countable noun.'),Q('curtsy',4,2,'Choose the correctly inflected past-tense sentence.',['The actor curtsied to the royal guests.','The actor curtsyed to the royal guests.','The actor curtsy to the royal guests yesterday.'],'The actor curtsied to the royal guests.','The y changes to i before -ed: curtsy becomes curtsied.') ]});
D('curvature',{etymology:E('curvature comes from Latin curvatura, from curvare “to bend”; the noun denotes the state or degree of being curved.','curvature'),contexts:[C('curvature.s1','道路测绘','Engineers reduced the road’s curvature near the bridge so trucks could follow the bend without crossing the centre line.','工程师减小了桥附近道路的弯曲度，使卡车能够沿弯道行驶而不越过中心线。','Engineers reduced the road’s curvature near the bridge / so trucks could follow the bend / without crossing the centre line.','curvature 为不可数/可数名词，描述弯曲程度；所有格表示道路的曲率。','道路曲率影响转弯轨迹，符合几何弯曲义。')],mistakes:[M('The road had zero curvature because it formed a tight circular loop.','The road had high curvature because it formed a tight circular loop.','紧密圆弧高度弯曲，不能说零曲率；零曲率对应直线。')],quiz:[Q('curvature',1,1,'A road with a sharp bend has?',['greater curvature than a straight road','zero curvature','no measurable shape'],'greater curvature than a straight road','Curvature measures how strongly a line or surface bends.'),Q('curvature',2,1,'In geometry, curvature is a measure of?',['how much a curve bends','how heavy a point is','how quickly a color fades'],'how much a curve bends','The mathematical term quantifies bending.'),Q('curvature',3,1,'Engineers inspect a pipe’s curvature to determine?',['how bent its path is','how loud water sounds','whether it tastes salty'],'how bent its path is','The pipe’s curve and degree of bending are at issue.'),Q('curvature',4,1,'A perfectly straight line has what curvature in elementary geometry?',['zero','infinite by definition','the same as a tight circle'],'zero','A straight line does not bend, so its curvature is zero.') ]});
D('curved',{etymology:E('curved is the past participle and adjective of curve, from Latin curvus “bent”; it describes a line or surface that is not straight.','curved'),contexts:[C('curved.s1','家具设计','The carpenter fitted a curved handrail along the staircase, shaping it to follow the wall and remain comfortable to grip.','木匠沿楼梯安装了一根弯曲扶手，使它贴合墙面并便于握住。','The carpenter fitted a curved handrail along the staircase / shaping it to follow the wall / and remain comfortable to grip.','curved 作定语形容词，修饰 handrail，指其形状不是直线。','扶手顺着墙面弯行，体现“弯曲的”义。')],mistakes:[M('The curved ruler lay perfectly straight from end to end with no bend at any point.','The straight ruler lay perfectly straight from end to end with no bend at any point.','没有任何弯曲的尺子应称 straight，与 curved 相反。','word-formation')],quiz:[Q('curved',1,1,'A curved line?',['bends instead of remaining straight','has no direction or shape','is always a closed square'],'bends instead of remaining straight','Curved describes a bent rather than straight form.'),Q('curved',2,1,'Which object is clearly curved?',['a crescent-shaped handle','a rigid straight rod','a flat square tile'],'a crescent-shaped handle','The crescent shape bends along its length.'),Q('curved',3,1,'A curved mirror differs from a flat mirror because its surface?',['bends inward or outward','is always a perfect cube','contains no reflective material'],'bends inward or outward','Curved describes a surface that bends rather than staying flat.'),Q('curved',4,1,'Choose the natural phrase.',['a curved staircase','a curved straight line with no bend','a curved temperature of 20 degrees'],'a curved staircase','A staircase can follow a bending path.') ]});
D('cushy',{etymology:E('cushy appeared in British slang in the nineteenth century, perhaps via Anglo-Indian usage; its exact origin is uncertain. It informally means easy or comfortable.','cushy'),contexts:[C('cushy.s1','工作安排','Compared with the night shift in the warehouse, her new desk job was cushy: regular hours, a padded chair, and no heavy lifting.','与仓库夜班相比，她的新文职工作轻松舒服得多：工时固定、椅子有软垫，也不用搬重物。','Compared with the night shift in the warehouse / her new desk job was cushy / regular hours / a padded chair / and no heavy lifting.','cushy 为非正式形容词，作表语评价工作轻松舒适。','固定工时且不需体力劳动，体现轻松安逸义。')],mistakes:[M('The cushy assignment required exhausting twelve-hour shifts outdoors in freezing rain.','The grueling assignment required exhausting twelve-hour shifts outdoors in freezing rain.','严寒中长时间高强度工作并不轻松或舒适，cushy 用法相反。','word-formation')],quiz:[Q('cushy',1,1,'A cushy job is usually?',['easy and comfortable','dangerous and physically exhausting','a type of office furniture'],'easy and comfortable','Cushy is informal for comfortable or undemanding.'),Q('cushy',2,1,'Which position sounds most cushy?',['a well-paid desk role with flexible hours','digging trenches through a storm','working double shifts without breaks'],'a well-paid desk role with flexible hours','The work conditions are unusually comfortable and easy.'),Q('cushy',3,1,'Calling an assignment cushy often implies that it?',['requires little effort compared with alternatives','is too difficult for anyone','has no connection to a job'],'requires little effort compared with alternatives','The adjective can describe an easy, favorable arrangement.'),Q('cushy',4,1,'Choose the sentence that uses cushy naturally.',['He landed a cushy post with short hours and generous benefits.','The cushy storm destroyed the bridge with icy winds.','She cushy the chair before sitting down.'],'He landed a cushy post with short hours and generous benefits.','The post is easy and comfortable, matching the informal adjective.') ]});
D('cuspidor',{etymology:E('cuspidor entered English through Portuguese cuspidouro or Spanish forms related to cuspir “to spit”; it names a receptacle for spitting.','cuspidor'),contexts:[C('cuspidor.s1','旧式公共场所','The caretaker removed the brass cuspidor from the station waiting room, where it had stood beside the tiled stove for decades.','管理员把黄铜痰盂从车站候车室移走；几十年来它一直放在瓷砖炉旁。','The caretaker removed the brass cuspidor from the station waiting room / where it had stood beside the tiled stove / for decades.','cuspidor 作可数名词，指供人吐痰的容器。','旧候车室里的容器用于吐痰，符合词义。')],mistakes:[M('The visitor used the cuspidor to serve hot tea to the waiting passengers.','The visitor used the teapot to serve hot tea to the waiting passengers.','cuspidor 是吐痰用容器，不是饮茶或盛饮料的壶。')],quiz:[Q('cuspidor',1,1,'A cuspidor is a receptacle used for?',['spitting','baking bread','storing letters'],'spitting','The noun names a spittoon.'),Q('cuspidor',2,1,'Where might a historical cuspidor have been placed?',['in a public waiting room','inside a sealed envelope','on a bicycle wheel'],'in a public waiting room','Spittoons were once kept in public indoor spaces.'),Q('cuspidor',3,1,'Which object is closest in function to a cuspidor?',['a spittoon','a teapot','a telescope'],'a spittoon','Cuspidor is another word for a spittoon.'),Q('cuspidor',4,1,'Choose the accurate sentence.',['The museum displayed a brass cuspidor from the nineteenth century.','The cuspidor boiled water for the museum café.','The cuspidor was a type of printed map.'],'The museum displayed a brass cuspidor from the nineteenth century.','A brass spittoon is an appropriate historical artifact.') ]});
D('custodial',{etymology:E('custodial derives from custodian, from Latin custos “guardian”; the adjective refers to guarding, supervising, or maintaining property or a person.','custodial'),contexts:[C('custodial.s1','设施管理','The school hired a custodial team to clean the classrooms each evening and report damaged locks before students returned.','学校聘请了一支保洁维护团队，每晚打扫教室，并在学生返校前报告损坏的门锁。','The school hired a custodial team / to clean the classrooms each evening / and report damaged locks / before students returned.','custodial 作定语形容词，说明团队承担场所维护与保洁职责。','清扫并检查校园设施属于场所维护义 s1。')],mistakes:[M('The custodial staff maintained the school by teaching algebra classes and grading every mathematics exam.','The teaching staff maintained the school’s instruction by teaching algebra classes and grading mathematics exams.','授课评分属于教师工作，不是 custodial 的保洁、看护或设施管理职责。')],quiz:[Q('custodial',1,1,'Custodial staff in a school generally handle?',['cleaning and basic care of the building','teaching every academic subject','writing the national curriculum'],'cleaning and basic care of the building','Custodial describes caretaking or maintenance duties.'),Q('custodial',2,1,'A custodial contract for an office may cover?',['janitorial cleaning and facility upkeep','financial investment advice only','the history of the building’s architect'],'janitorial cleaning and facility upkeep','Cleaning and upkeep are custodial services.'),Q('custodial',3,1,'Which is a custodial task?',['repairing a broken door closer and cleaning the hall','examining a patient’s blood sample','translating a novel into French'],'repairing a broken door closer and cleaning the hall','Maintaining the premises is custodial work.'),Q('custodial',4,1,'“Custodial care of the building” means?',['ongoing maintenance and oversight','ownership of every item inside','temporary decoration for a festival'],'ongoing maintenance and oversight','Custodial conveys responsibility for looking after the property.') ]});
D('custodian',{etymology:E('custodian came through Medieval Latin custodianus from Latin custos, “guardian”; the noun names a person who guards, maintains, or has legal care of someone.','custodian'),contexts:[C('custodian.s1','资料馆管理','The archive’s custodian recorded each box’s location and checked the humidity before researchers were allowed into the storage room.','档案馆管理员记录每个箱子的存放位置，并在研究人员进入库房前检查湿度。','The archive’s custodian recorded each box’s location / and checked the humidity / before researchers were allowed into the storage room.','custodian 作可数名词，指负责保护和管理场所或物品的人。','管理员保护档案并维持适当环境，符合保管人义 s1。'),C('custodian.s2','儿童监护','After the hearing, the court appointed the child’s aunt as custodian, giving her legal responsibility for the girl’s daily care.','听证会后，法院指定女孩的姨妈为监护人，赋予她照料女孩日常生活的法律责任。','After the hearing / the court appointed the child’s aunt as custodian / giving her legal responsibility / for the girl’s daily care.','appoint someone as custodian 指定其承担法律监护责任。','法院委托亲属照护未成年人，符合监护人义 s2。')],mistakes:[M('The custodian of the archive was legally responsible for the child’s custody, although she had no connection to the child and only maintained the building.','The child’s legal custodian was responsible for her care; the archive custodian maintained the building.','仅维护档案楼的人不因此成为儿童监护人；两种 custodian 职责须按对象区分。')],quiz:[Q('custodian',1,1,'A library custodian is most likely responsible for?',['looking after the building and its contents','writing every book in the collection','deciding national election results'],'looking after the building and its contents','A custodian takes care of a place or property.'),Q('custodian',2,2,'A court-appointed custodian of a child has?',['legal responsibility for the child’s care','exclusive ownership of the courthouse','the duty to clean the courtroom only'],'legal responsibility for the child’s care','The second sense is a person legally entrusted with someone’s care.'),Q('custodian',3,1,'Which person is a custodian in the property-care sense?',['the caretaker who secures a museum collection','a visitor who buys a ticket','an artist whose painting hangs in the museum'],'the caretaker who secures a museum collection','Securing and caring for the collection matches the role.'),Q('custodian',4,2,'If a guardian is named custodian, the title concerns?',['care and responsibility for another person','repair of the building’s roof','ownership of a museum artifact'],'care and responsibility for another person','A custodian may be entrusted with another person’s welfare.') ]});
D('customarily',{etymology:E('customarily is formed from customary, from custom plus -ary, and the adverb suffix -ly; custom came through French from Latin consuetudo “habit or practice.”','customarily'),contexts:[C('customarily.s1','婚礼习俗','In the coastal village, families customarily serve fish soup at the wedding feast, following a practice passed down for generations.','在这个沿海村庄，家人通常会在婚宴上供应鱼汤，这一习俗已传承数代。','In the coastal village / families customarily serve fish soup / at the wedding feast / following a practice passed down for generations.','customarily 修饰 serve，表示按惯例或习俗经常如此。','代代相传的婚宴做法说明这是当地通常习惯。')],mistakes:[M('The village customarily held its annual festival once in its entire history and never repeated the event.','The village held its annual festival customarily, repeating the event as an established tradition.','customarily 表示依照习惯、惯常地；只发生一次且从不重现不构成习惯。')],quiz:[Q('customarily',1,1,'If a town customarily closes shops at noon, it?',['usually follows that established practice','did so only once by accident','never closes a shop'],'usually follows that established practice','The adverb means according to custom or usual practice.'),Q('customarily',2,1,'Which sentence best uses customarily?',['Residents customarily greet the festival with a lantern walk.','Residents customarily greeted it once and banned it forever.','Residents customarily means a lantern.'],'Residents customarily greet the festival with a lantern walk.','The sentence describes a customary recurring practice.'),Q('customarily',3,1,'“The chair is customarily reserved for the eldest guest” means?',['it is usually reserved that way','it is reserved only after being repaired','the chair itself is a custom'],'it is usually reserved that way','Customarily marks what is normally done.'),Q('customarily',4,1,'Choose the closest synonym in context: “The office customarily sends notices by mail.”',['usually','rarely and unexpectedly','never'],'usually','Customarily means as a matter of established routine.') ]});
D('cuticle',{etymology:E('cuticle comes from Latin cuticula, a diminutive of cutis “skin”; it names a thin outer layer, especially around a nail or on a plant.','cuticle'),contexts:[C('cuticle.s1','皮肤与指甲','The manicurist softened the cuticle around each nail before pushing it back gently with a wooden tool.','美甲师先软化每片指甲周围的角质层，再用木工具轻轻将它推回。','The manicurist softened the cuticle around each nail / before pushing it back gently / with a wooden tool.','cuticle 作可数名词，指甲根部的一层薄皮或角质层。','护理动作发生在指甲周围的薄层，符合 s1。')],mistakes:[M('The manicurist trimmed the cuticle, the hard bone at the centre of each finger.','The manicurist cared for the cuticle, the thin skin around the base of each nail.','cuticle 是薄层皮肤/角质层，不是手指中的骨头。')],quiz:[Q('cuticle',1,1,'The cuticle around a fingernail is?',['a thin layer of skin at its base','the finger bone beneath the nail','a painted metal covering'],'a thin layer of skin at its base','In nail care, cuticle names the thin skin bordering the nail.'),Q('cuticle',2,1,'A plant cuticle helps cover the plant’s?',['outer surface','root system only','seed’s inner embryo only'],'outer surface','In botany, the cuticle is a protective outer layer.'),Q('cuticle',3,1,'Where would a manicurist find the cuticle?',['around the base of a nail','inside the elbow joint','under the sole of a shoe'],'around the base of a nail','The nail cuticle is the thin tissue at the nail’s base.'),Q('cuticle',4,1,'Choose a correct phrase.',['the cuticle around the nail','the cuticle of the finger bone marrow','a cuticle of three litres'],'the cuticle around the nail','The collocation points to the thin skin around a nail.') ]});
D('cutting',{etymology:E('cutting is formed from cut plus -ing; as a noun it may be a piece cut from a plant or a printed extract, while the related verb can describe making a road cut.','cutting'),contexts:[C('cutting.s1','园艺繁殖','She planted a rosemary cutting in moist soil and kept it near the window until new roots appeared.','她把一段迷迭香插条种在湿润土壤里，放在窗边，直到长出新根。','She planted a rosemary cutting in moist soil / and kept it near the window / until new roots appeared.','cutting 作可数名词，指从植物上剪下、用于繁殖的插枝。','剪下的枝段长出根后可培育新植株，符合 s1。'),C('cutting.s1','新闻剪报','The researcher saved a cutting from the local newspaper that described the opening of the first bridge.','研究人员保存了一份当地报纸剪报，内容是第一座桥的启用。','The researcher saved a cutting from the local newspaper / that described the opening / of the first bridge.','newspaper cutting 指从报纸剪下并保存的文章或片段。','研究人员剪下并保存地方报纸的一篇报道，符合剪报义 s1。')],mistakes:[M('She called the entire rooted rosemary bush a cutting, although it had grown in the garden for twenty years.','She called a small stem clipped from the rosemary bush a cutting before planting it to root.','cutting 指剪下的植物部分，不是已生长多年的整株灌木。')],quiz:[Q('cutting',1,1,'A gardener roots a rose cutting by?',['planting a clipped stem so it grows roots','lifting an entire mature orchard','painting a flower pot'],'planting a clipped stem so it grows roots','A plant cutting is a piece removed for propagation.'),Q('cutting',2,1,'A newspaper cutting is?',['an article or extract clipped from a newspaper','a new kind of printing press','a whole tree from a garden'],'an article or extract clipped from a newspaper','The noun also means a clipping saved from a publication.'),Q('cutting',3,1,'Which item is a horticultural cutting?',['a short stem removed from a parent plant','a stone placed beside a flower bed','a seed packet’s printed price'],'a short stem removed from a parent plant','The stem is removed and can be propagated.'),Q('cutting',4,1,'The archive’s cutting file contains?',['saved newspaper clippings','only uncut sheets of blank paper','live seedlings in pots'],'saved newspaper clippings','A cutting file commonly stores clipped articles.') ]});
D('cuttlefish',{etymology:E('cuttlefish is an English compound naming the marine animal; the origin of cuttle is uncertain. It is a cephalopod related to squid and octopuses, not a true fish.','cuttlefish'),contexts:[C('cuttlefish.s1','海洋生物','A cuttlefish changed from sandy brown to pale grey as it crossed the aquarium floor, matching the shifting patches of light.','一只乌贼穿过水族箱底部时，从沙棕色变成浅灰色，以此呼应不断变化的光斑。','A cuttlefish changed from sandy brown to pale grey / as it crossed the aquarium floor / matching the shifting patches of light.','cuttlefish 作可数名词，指乌贼类海洋头足动物。','变色并在海底移动的动物是乌贼，符合 s1。')],mistakes:[M('A cuttlefish is a bony freshwater fish with scales and gills, closely related to trout.','A cuttlefish is a marine cephalopod related to squid and octopuses.','乌贼不是有鳞的硬骨鱼，而是海生头足类。','confusable')],quiz:[Q('cuttlefish',1,1,'A cuttlefish belongs to the group that includes?',['squid and octopuses','trout and salmon','frogs and toads'],'squid and octopuses','Cuttlefish are cephalopods related to squid and octopuses.'),Q('cuttlefish',2,1,'A cuttlefish can change its appearance chiefly to?',['blend with its surroundings','grow feathers for flight','turn into a true bony fish'],'blend with its surroundings','Many cuttlefish use rapid color and pattern changes for camouflage.'),Q('cuttlefish',3,1,'Despite its name, a cuttlefish is not a true?',['fish','marine animal','cephalopod'],'fish','It is a molluscan cephalopod, not a fish.'),Q('cuttlefish',4,1,'Where would you most naturally observe a cuttlefish?',['in a marine aquarium','in a desert cactus garden','on a mountain glacier'],'in a marine aquarium','Cuttlefish are marine animals.') ]});
D('cyan',{etymology:E('cyan comes from Greek kyanos, “dark blue,” through the prefix cyano-; the English color name refers to a greenish blue.','cyan'),contexts:[C('cyan.s1','印刷配色','The printer adjusted the cyan ink until the turquoise sky in the travel poster matched the designer’s proof.','印刷工调整青色墨水，直到旅游海报上的蓝绿色天空与设计师的打样一致。','The printer adjusted the cyan ink / until the turquoise sky in the travel poster / matched the designer’s proof.','cyan 作颜色名词作定语修饰 ink，表示青蓝色墨水。','蓝绿色印刷墨与目标颜色匹配，符合色彩义。')],mistakes:[M('The cyan square was a vivid greenish blue, although the report called it pure red.','The cyan square was a vivid greenish blue, so the report identified it as cyan.','青色是偏绿的蓝色；称为纯红色与色名不相符。','confusable')],quiz:[Q('cyan',1,1,'Cyan is closest to which color?',['greenish blue','deep scarlet','yellow-orange'],'greenish blue','Cyan is a blue-green color.'),Q('cyan',2,1,'In four-color printing, cyan is used as?',['one of the principal ink colors','a type of paper grain','the name of a red dye only'],'one of the principal ink colors','Cyan is one of the standard process-color inks.'),Q('cyan',3,1,'Which pair best describes cyan?',['blue with a greenish cast','black mixed with brown','bright red with violet'],'blue with a greenish cast','This captures the usual color range of cyan.'),Q('cyan',4,1,'A cyan label on a paint sample most likely indicates?',['a turquoise-like blue-green shade','a pure white with no hue','a dark orange'],'a turquoise-like blue-green shade','Cyan shades lie in the blue-green part of the spectrum.') ]});
D('cyanide',{etymology:E('cyanide was formed from cyanogen, named from Greek kyanos “blue,” plus the chemical suffix -ide; it names a salt or compound containing the cyanide group.','cyanide'),contexts:[C('cyanide.s1','化学安全','The laboratory stored the cyanide standard in a locked cabinet and required double gloves whenever trained staff handled the sealed vial.','实验室把氰化物标准品存放在上锁柜中，并要求受训人员处理密封小瓶时戴双层手套。','The laboratory stored the cyanide standard in a locked cabinet / and required double gloves / whenever trained staff handled the sealed vial.','cyanide 作不可数/可数化学名词，指有毒的氰化物。','上锁、密封和防护说明这是需严格控制的氰化物试剂。'),C('cyanide.s2','金属加工','The technician cyanided the small metal parts under controlled industrial conditions to produce a protective finish.','技术人员在严格控制的工业条件下用氰化物处理小金属零件，以形成保护性表层。','The technician cyanided the small metal parts / under controlled industrial conditions / to produce a protective finish.','cyanide 作及物动词，过去式 cyanided，表示用氰化物处理。','金属被氰化物处理形成表层，体现动词义 s2。')],mistakes:[M('The lab labeled the cyanide vial harmless table salt and left it beside the communal coffee pot.','The lab labeled the cyanide vial as a toxic chemical and kept it securely stored.','氰化物具有高度毒性，不能当作无害食盐或放在公共饮水旁。')],quiz:[Q('cyanide',1,1,'Cyanide is best described as?',['a highly toxic chemical compound or group','a harmless kitchen seasoning','a blue-green fabric dye only'],'a highly toxic chemical compound or group','Cyanides are chemical compounds, many of which are highly toxic.'),Q('cyanide',2,2,'If an industrial process cyanides a part, it?',['treats it with a cyanide compound','paints it cyan blue with no chemical reaction','cuts it into a cylinder'],'treats it with a cyanide compound','The verb means to subject metal to cyanide treatment.'),Q('cyanide',3,1,'Which response to a cyanide spill is appropriate?',['Follow hazardous-material procedures and isolate the area.','Taste the material to identify it.','Pour it into a public sink without protection.'],'Follow hazardous-material procedures and isolate the area.','Cyanide compounds require strict safety handling.'),Q('cyanide',4,2,'Choose the verb use of cyanide.',['The factory cyanided the parts in a controlled process.','The cyanide was sealed in a cabinet.','Cyanide is a chemical name on the label.'],'The factory cyanided the parts in a controlled process.','Here cyanided is a transitive verb describing chemical treatment.') ]});
D('cyclic',{etymology:E('cyclic is formed from cycle, from Greek kyklos “circle,” plus -ic; it describes events or structures that return in a repeating cycle.','cyclic'),contexts:[C('cyclic.s1','生态研究','The ecologist modeled cyclic changes in algae growth, with populations rising in warm months and falling after nutrient levels dropped.','生态学家模拟藻类生长的周期性变化：暖季数量上升，养分水平下降后数量又减少。','The ecologist modeled cyclic changes in algae growth / with populations rising in warm months / and falling after nutrient levels dropped.','cyclic 修饰 changes，表示变化反复经历一轮轮周期。','藻类数量按季节和养分变化而重复起落，符合周期义。')],mistakes:[M('The cyclic process happened once and could never recur under any conditions.','The one-time process happened once and could never recur under any conditions.','只发生一次且绝不重现的事件不具备 cyclic 的循环性。','word-formation')],quiz:[Q('cyclic',1,1,'A cyclic pattern?',['repeats in a cycle','occurs once and never returns','has no relation to time'],'repeats in a cycle','Cyclic means recurring in a cycle.'),Q('cyclic',2,1,'A cyclic economic trend might?',['rise and fall in a recurring pattern','remain unchanged forever','occur only at one exact place'],'rise and fall in a recurring pattern','The adjective describes repeated phases.'),Q('cyclic',3,1,'Which process is most clearly cyclic?',['a tide that rises and falls each day','a single meteor impact with no recurrence','a fixed ruler lying on a desk'],'a tide that rises and falls each day','The tide follows a repeated cycle.'),Q('cyclic',4,1,'A researcher calls a change cyclic because it?',['returns through the same stages repeatedly','cannot be measured','has happened only once'],'returns through the same stages repeatedly','Recurrence through stages is the core sense.') ]});
D('cyclical',{etymology:E('cyclical is formed from cycle, ultimately Greek kyklos “circle,” with the adjective-forming ending -ical; it means recurring in cycles.','cyclical'),contexts:[C('cyclical.s1','市场波动','The analyst described demand for heating oil as cyclical, increasing each autumn and easing when spring temperatures returned.','分析师把取暖油需求称为周期性的：每到秋季就上升，春季气温回升后又下降。','The analyst described demand for heating oil as cyclical / increasing each autumn / and easing when spring temperatures returned.','cyclical 作表语形容词，描述规律性重复的变化。','需求随着季节反复升降，符合 cyclical 的周期义。')],mistakes:[M('Demand was cyclical because it peaked once in history and never followed a recurring pattern.','Demand was a one-time spike because it peaked once in history and never followed a recurring pattern.','不重复的单次变化不属于 cyclical pattern。','word-formation')],quiz:[Q('cyclical',1,1,'Cyclical demand changes?',['recur in a regular sequence','remain exactly flat at every moment','occur only once in history'],'recur in a regular sequence','Cyclical describes phenomena that recur in cycles.'),Q('cyclical',2,1,'Which is a cyclical pattern?',['sales rise every holiday season and fall afterward','a one-time sale caused by a single emergency','a number printed on a permanent sign'],'sales rise every holiday season and fall afterward','Repeated seasonal rises and falls form a cycle.'),Q('cyclical',3,1,'If unemployment is cyclical, it tends to?',['move through recurring expansions and downturns','stay at zero forever','change only when someone changes its spelling'],'move through recurring expansions and downturns','The adjective signals recurring phases over time.'),Q('cyclical',4,1,'Which statement distinguishes cyclical from one-off?',['A cyclical event repeats; a one-off event does not.','They both mean that something happens only once.','Cyclical means physically shaped like a cube.'],'A cyclical event repeats; a one-off event does not.','The recurring nature is what sets cyclical apart.') ]});
D('cycling',{etymology:E('cycling is the -ing form of cycle; when used as a noun, it names the sport or activity of riding a bicycle. Cycle ultimately comes from Greek kyklos “circle.”','cycling'),contexts:[C('cycling.s1','体育训练','Cycling along the river path before breakfast helped Lena build endurance without adding traffic noise to her training route.','早餐前沿河道骑自行车帮助莉娜增强耐力，同时避免训练路线上的车流噪声。','Cycling along the river path before breakfast / helped Lena build endurance / without adding traffic noise to her training route.','cycling 作不可数活动名词，指骑自行车这项运动或活动。','沿河骑行作为训练，体现骑车活动义。')],mistakes:[M('Cycling is the sport of swimming across a pool while wearing a bicycle helmet.','Swimming is the sport of crossing a pool; cycling is the activity of riding a bicycle.','游泳不是 cycling；词义要求骑自行车。','confusable')],quiz:[Q('cycling',1,1,'Cycling as a sport involves?',['riding a bicycle','swimming laps','climbing a ladder'],'riding a bicycle','Cycling names the activity of riding bicycles.'),Q('cycling',2,1,'A cycling club is most likely to organize?',['group bicycle rides','a chess tournament on horseback','a cooking class for cyclists only'],'group bicycle rides','The club centers on bicycle riding.'),Q('cycling',3,1,'Which person is engaged in cycling?',['a rider pedaling along a marked road route','a swimmer using a kickboard','a driver waiting at a traffic light'],'a rider pedaling along a marked road route','Pedaling a bicycle is cycling.'),Q('cycling',4,1,'Choose the natural use.',['She took up cycling for exercise.','She cycling the lock with a key.','The cycling of the soup made it salty.'],'She took up cycling for exercise.','Cycling functions naturally as the name of the activity.') ]});
D('cyclist',{etymology:E('cyclist is formed from cycle, ultimately Greek kyklos “circle,” plus the agent suffix -ist; it names someone who rides a bicycle.','cyclist'),contexts:[C('cyclist.s1','道路安全','The cyclist signaled before turning left and waited until the truck driver could see her in the side mirror.','骑车者左转前打了手势，并等到卡车司机能从侧镜看到她后才转弯。','The cyclist signaled before turning left / and waited until the truck driver could see her / in the side mirror.','cyclist 作可数名词，指骑自行车的人。','她骑车、打转向手势并与车辆共享道路，符合 s1。')],mistakes:[M('The cyclist swam beside the bicycle for three kilometres without ever riding or pedaling it.','The swimmer swam beside the bicycle for three kilometres without riding or pedaling it.','只游泳而未骑车的人不应称为 cyclist。','confusable')],quiz:[Q('cyclist',1,1,'A cyclist is a person who?',['rides a bicycle','repairs only aircraft engines','swims competitively'],'rides a bicycle','The suffix -ist identifies a person who practices or participates in cycling.'),Q('cyclist',2,1,'A helmeted cyclist on a bike lane is?',['a bicycle rider','a pedestrian walking a dog','a passenger on a train'],'a bicycle rider','A cyclist rides a bicycle, often on a bike lane.'),Q('cyclist',3,1,'Which safety action is especially relevant to a cyclist?',['signaling before turning','checking a ship’s anchor','wearing a diving mask to breathe underwater'],'signaling before turning','Cyclists share roads and should signal their turns.'),Q('cyclist',4,1,'Choose the correct sentence.',['The cyclist repaired a flat tire beside the path.','The cyclist paddled a canoe across the lake.','The cyclist flew the plane over the coast.'],'The cyclist repaired a flat tire beside the path.','A bicycle rider may repair a tire on the route.') ]});
D('cyclotron',{etymology:E('cyclotron is a modern scientific coinage built on cyclo- “circular” and -tron, a suffix used for particle-accelerating devices; it names a circular accelerator.','cyclotron'),contexts:[C('cyclotron.s1','粒子物理','Researchers sent charged particles through the cyclotron, where an alternating electric field accelerated them along an expanding spiral path.','研究人员把带电粒子送入回旋加速器，交变电场使粒子沿不断扩大的螺旋轨迹加速。','Researchers sent charged particles through the cyclotron / where an alternating electric field accelerated them / along an expanding spiral path.','cyclotron 作可数名词，指利用磁场和交变电场加速粒子的装置。','带电粒子在设备中沿弯曲轨迹加速，符合回旋加速器义。')],mistakes:[M('The laboratory used a cyclotron to cool soup by stirring it slowly in a kitchen bowl.','The laboratory used a centrifuge to separate liquid samples by spinning them.','回旋加速器加速带电粒子，不是厨房搅拌器或冷却设备。')],quiz:[Q('cyclotron',1,1,'A cyclotron is a device used to?',['accelerate charged particles','measure rainfall in a garden','refrigerate food'],'accelerate charged particles','Cyclotrons accelerate particles using electromagnetic fields.'),Q('cyclotron',2,1,'The “cyclo-” element in cyclotron alludes to?',['the curved or circular particle path','a cooling cycle of soup','the device’s color'],'the curved or circular particle path','The machine guides particles around a circular path.'),Q('cyclotron',3,1,'Which facility is most likely to operate a cyclotron?',['a nuclear physics research laboratory','a bicycle repair shop','a greenhouse seed library'],'a nuclear physics research laboratory','Cyclotrons are scientific particle accelerators.'),Q('cyclotron',4,1,'Researchers direct particles through a cyclotron to study?',['their behavior at high energies','the taste of cooking oil','how to grow flowers without light'],'their behavior at high energies','The accelerator supplies energy for experimental physics.') ]});
D('cylindrical',{etymology:E('cylindrical is formed from cylinder plus -ical; cylinder derives from Greek kylindros “roller.” The adjective means shaped like a cylinder.','cylindrical'),contexts:[C('cylindrical.s1','容器形状','The cylindrical rain barrel fit beneath the downspout, its curved side holding water while the flat top kept leaves out.','圆筒形雨水桶正好放在落水管下方，弯曲的桶身盛水，平顶则挡住落叶。','The cylindrical rain barrel fit beneath the downspout / its curved side holding water / while the flat top kept leaves out.','cylindrical 作定语形容词，描述具有圆柱体外形。','桶身环绕轴线呈圆柱形，符合 s1。')],mistakes:[M('The cylindrical container was a flat triangular plate with no curved side or circular cross-section.','The triangular container was a flat plate with no cylindrical side or circular cross-section.','平坦三角板不具圆形横截面或圆柱形状。')],quiz:[Q('cylindrical',1,1,'A cylindrical pipe has a shape like?',['a long tube with a circular cross-section','a flat square sheet','a pointed cone with a circular base'],'a long tube with a circular cross-section','A cylinder has circular ends and a curved side.'),Q('cylindrical',2,1,'Which object is cylindrical?',['a soup can','a triangular road sign','a flat sheet of paper'],'a soup can','A can has a circular top and bottom with a curved side.'),Q('cylindrical',3,1,'In a cylindrical tank, the side walls are?',['curved around a circular axis','all flat and triangular','shaped as a single sharp point'],'curved around a circular axis','The cylinder’s lateral surface curves around its axis.'),Q('cylindrical',4,1,'A cylindrical column would most likely be?',['round in cross-section and column-shaped','a flat disk with no height','a cube with square sides'],'round in cross-section and column-shaped','The adjective indicates a cylinder-like form.') ]});
D('cytology',{etymology:E('cytology combines cyto- from Greek kytos “cell or hollow vessel” and -logy from logos “study”; it is the biological study of cells.','cytology'),contexts:[C('cytology.s1','医学实验室','In cytology, the technician stained the cells on a slide so the pathologist could examine their size and internal features.','在细胞学检查中，技术员给载玻片上的细胞染色，以便病理学家观察其大小和内部特征。','In cytology / the technician stained the cells on a slide / so the pathologist could examine their size and internal features.','cytology 作不可数学科名词，指细胞的研究。','染色并检查细胞形态属于细胞学工作。')],mistakes:[M('Cytology is the study of weather systems, including cloud formation and seasonal rainfall.','Meteorology is the study of weather systems, including cloud formation and seasonal rainfall.','天气研究属于气象学；cytology 研究细胞。','confusable')],quiz:[Q('cytology',1,1,'Cytology is the study of?',['cells','weather patterns','ancient architecture'],'cells','The combining form cyto- means cell.'),Q('cytology',2,1,'A cytology lab is likely to examine?',['cells collected on a microscope slide','the orbit of a distant planet','the strength of a bridge cable'],'cells collected on a microscope slide','Microscopic cell examination is central to cytology.'),Q('cytology',3,1,'Which professional field uses cytology?',['cell biology and diagnostic pathology','marine navigation','music composition'],'cell biology and diagnostic pathology','Both fields may analyze cells.'),Q('cytology',4,1,'The suffix -logy in cytology means?',['study or branch of knowledge','a person who sells cells','a chemical color'],'study or branch of knowledge','-logy forms names of fields of study.') ]});
D('cytoplasm',{etymology:E('cytoplasm combines cyto- “cell” and plasm, from Greek plasma “something formed”; it names the material inside a cell outside the nucleus.','cytoplasm'),contexts:[C('cytoplasm.s1','细胞结构','Under the microscope, the researcher watched vesicles move through the cytoplasm between the cell membrane and the nucleus.','在显微镜下，研究人员观察到囊泡在细胞膜与细胞核之间的细胞质中移动。','Under the microscope / the researcher watched vesicles move through the cytoplasm / between the cell membrane and the nucleus.','cytoplasm 作不可数名词，指细胞核之外、细胞膜之内的细胞内容物。','囊泡位于细胞膜与细胞核之间，符合细胞质的空间位置。')],mistakes:[M('The cytoplasm is the rigid outer wall of a plant cell, located entirely outside the cell membrane.','The cell wall is the rigid outer layer of a plant cell; cytoplasm lies inside the membrane and outside the nucleus.','细胞质位于细胞膜内；植物细胞壁才是外层刚性结构。')],quiz:[Q('cytoplasm',1,1,'Cytoplasm is found?',['inside the cell membrane but outside the nucleus','outside every part of the cell','only inside the nucleus'],'inside the cell membrane but outside the nucleus','This defines the usual location of cytoplasm.'),Q('cytoplasm',2,1,'Many cell structures are suspended in the?',['cytoplasm','cell wall only','nuclear envelope only'],'cytoplasm','The cytoplasm is the cell material in which organelles are suspended.'),Q('cytoplasm',3,1,'Which structure separates cytoplasm from the external environment?',['the cell membrane','the nucleolus','a chromosome'],'the cell membrane','The membrane surrounds the cell contents.'),Q('cytoplasm',4,1,'A diagram labels the region around the nucleus but within the cell membrane. That region is?',['cytoplasm','a ribosome alone','the surrounding air'],'cytoplasm','Cytoplasm occupies the intracellular region outside the nucleus.') ]});
D('dadaism',{etymology:E('dadaism is named from Dada, the early twentieth-century avant-garde movement; the origin of the chosen word Dada is uncertain. The suffix -ism marks the movement or doctrine.','dadaism'),contexts:[C('dadaism.s1','艺术史课程','The lecture introduced Dadaism through collages that disrupted ordinary logic and mocked the idea that art had to be beautiful.','讲座通过打破日常逻辑、嘲弄“艺术必须美”的观念的拼贴作品，介绍了达达主义。','The lecture introduced Dadaism through collages / that disrupted ordinary logic / and mocked the idea / that art had to be beautiful.','Dadaism 作艺术运动名词；通过作品解释其反传统立场。','拼贴、反逻辑与挑战传统艺术观是达达主义的特点。')],mistakes:[M('Dadaism demanded realistic portraits and strict academic rules, rejecting playful experiments and nonsense.','Academic classicism demanded strict realistic rules, while Dadaism embraced playful experiments and anti-rational provocation.','达达主义以反理性和反传统著称，不以严格学院写实为纲领。')],quiz:[Q('dadaism',1,1,'Dadaism is associated with?',['avant-garde art that challenged convention','the study of cell membranes','a system of measuring rainfall'],'avant-garde art that challenged convention','Dada was an anti-establishment artistic movement.'),Q('dadaism',2,1,'A Dadaist collage might deliberately?',['combine unrelated images to unsettle conventional meaning','follow a rigid photographic copy of nature','avoid all experimentation'],'combine unrelated images to unsettle conventional meaning','Dadaists often used chance, collage, and absurdity.'),Q('dadaism',3,1,'Which idea fits Dadaism most closely?',['art may challenge accepted standards','art must always imitate reality exactly','art can only be made from stone'],'art may challenge accepted standards','The movement resisted conventional definitions of art.'),Q('dadaism',4,1,'A museum display on Dadaism would most likely include?',['experimental collages and provocative works','only botanical specimens','a chart of bicycle gears'],'experimental collages and provocative works','Such works represent the movement’s experimental approach.') ]});
D('daddy',{etymology:E('daddy is a familiar, affectionate form of dad; dad and daddy belong to widespread child-language forms, and their deeper origin is uncertain.','daddy'),contexts:[C('daddy.s1','家庭对话','“Daddy, can you read the last chapter?” the child asked, holding out the book she had been saving for bedtime.','孩子把一直留到睡前读的书递过去，问：“爸爸，你能读最后一章吗？”','“Daddy, can you read the last chapter?” / the child asked / holding out the book / she had been saving for bedtime.','Daddy 是对父亲的亲昵称呼，常用于家庭口语。','孩子在家庭场景中亲切地称呼父亲，符合 s1。')],mistakes:[M('The child addressed a complete stranger as her daddy even though he was not her father or guardian.','The child addressed her father as Daddy, the familiar name she used at home.','若无亲属/照护关系，把陌生人称为自己的 daddy 会错指身份。')],quiz:[Q('daddy',1,1,'A child who says “Daddy, look!” is addressing?',['her father','the family’s dentist by job title','a bicycle mechanic'],'her father','Daddy is an affectionate familiar word for father.'),Q('daddy',2,1,'Which register best fits daddy?',['informal and affectionate','strictly scientific','a formal legal term for a creditor'],'informal and affectionate','The word is usually a familiar family term.'),Q('daddy',3,1,'Choose the natural sentence.',['The toddler ran to her daddy after school.','The toddler measured the daddy of the microscope.','She daddy the letter before mailing it.'],'The toddler ran to her daddy after school.','The noun refers affectionately to a father.'),Q('daddy',4,1,'In a formal report, “the child’s father” is generally more suitable than?',['the child’s daddy','the child’s legal guardian','the child’s parent'],'the child’s daddy','Daddy is conversational and affectionate, while father is neutral/formal.') ]});
D('daffodil',{etymology:E('daffodil came through Dutch affodil from asphodel, the name of a flowering plant, with the initial d likely arising through the phrase the affodil; the remote history is uncertain.','daffodil'),contexts:[C('daffodil.s1','春日园艺','Yellow daffodils opened beside the stone path in March, their trumpet-shaped centres bright against the wet soil.','三月，石径旁的黄色水仙盛开，喇叭形花冠在湿润的泥土映衬下格外鲜亮。','Yellow daffodils opened beside the stone path in March / their trumpet-shaped centres bright / against the wet soil.','daffodil 作可数名词，指春季开花的水仙属植物。','黄色春花和喇叭形副花冠是常见水仙特征。')],mistakes:[M('The gardener planted daffodils that bloomed as blue roses with long woody trunks.','The gardener planted daffodils that bloomed as yellow trumpet-shaped spring flowers.','水仙不是蓝玫瑰或木本树；这种描写与花的基本特征不符。')],quiz:[Q('daffodil',1,1,'A daffodil is a spring-flowering?',['plant with a trumpet-shaped flower','large marine mammal','type of garden spade'],'plant with a trumpet-shaped flower','Daffodils are familiar spring bulbs with a central trumpet.'),Q('daffodil',2,1,'Where might daffodils commonly bloom?',['in a spring garden','under the ocean surface','inside a metal tool chest'],'in a spring garden','Daffodils are garden flowers that typically bloom in spring.'),Q('daffodil',3,1,'Which image most likely shows daffodils?',['yellow flowers with central trumpets','red fruit hanging from a tree','a field of white mushrooms'],'yellow flowers with central trumpets','The trumpet-like corona is a distinctive feature.'),Q('daffodil',4,1,'Choose the natural collocation.',['a bunch of daffodils','a daffodil of cyanide','a daffodil drove the tractor'],'a bunch of daffodils','Daffodils are countable flowers often gathered in bunches.') ]});
D('dagger',{etymology:E('dagger entered English through Old French dague, “a short stabbing weapon”; its deeper European origin is uncertain. It names a short pointed blade and can also be a verb.','dagger'),contexts:[C('dagger.s1','历史展览','The display case held a ceremonial dagger with a narrow blade, an engraved handle, and a leather sheath.','展柜里陈列着一把仪式短匕首，刀刃狭长，刀柄带有雕刻，并配有皮鞘。','The display case held a ceremonial dagger / with a narrow blade / an engraved handle / and a leather sheath.','dagger 作可数名词，指短而尖的刀具。','窄刃、刀柄和刀鞘说明这是匕首，符合 s1。'),C('dagger.s2','文学表达','The villain daggered the guard in the novel, then dropped the weapon while escaping through the courtyard.','小说中的反派用匕首刺了守卫，随后穿过庭院逃跑时丢下了武器。','The villain daggered the guard in the novel / then dropped the weapon / while escaping through the courtyard.','dagger 可作及物动词，表示用匕首刺。','人物以匕首刺伤守卫，符合动词义 s2。')],mistakes:[M('The museum displayed a dagger, a blunt wooden spoon designed only for stirring soup.','The museum displayed a dagger, a short pointed blade designed for stabbing.','钝木勺不是短尖刀具，不能称为 dagger。')],quiz:[Q('dagger',1,1,'A dagger is a?',['short pointed weapon','long-handled cooking ladle','round shield with no blade'],'short pointed weapon','The noun denotes a short stabbing knife.'),Q('dagger',2,2,'To dagger someone in a story means to?',['stab the person with a dagger','give the person a written award','measure the person’s height'],'stab the person with a dagger','The verb is derived from the weapon and means stab with it.'),Q('dagger',3,1,'Which object is most likely a dagger?',['a short double-edged blade in a sheath','a broad wooden serving tray','a blunt ruler'],'a short double-edged blade in a sheath','The short pointed blade is characteristic of a dagger.'),Q('dagger',4,2,'In “the assassin daggered the sentry,” daggered is?',['a transitive verb describing a stabbing','a noun for the sentry’s helmet','an adjective meaning harmless'],'a transitive verb describing a stabbing','The verb takes an object, the person stabbed.') ]});
D('daguerreotype',{etymology:E('daguerreotype is named after French inventor Louis Daguerre, who developed the early photographic process; Greek typos “impression” forms the second element.','daguerreotype'),contexts:[C('daguerreotype.s1','摄影史','The family archive contained a daguerreotype of an ancestor, its mirror-like image sealed behind glass in a small brass case.','家族档案里有一张祖先的达盖尔银版照片，镜面般的影像密封在小黄铜盒的玻璃后面。','The family archive contained a daguerreotype of an ancestor / its mirror-like image sealed behind glass / in a small brass case.','daguerreotype 作可数名词，指早期银版摄影作品。','镜面影像、玻璃密封和金属盒是银版照片的典型呈现。')],mistakes:[M('The archive labeled a digital color selfie taken yesterday as a daguerreotype from the 1840s.','The archive labeled a small nineteenth-century silvered-plate photograph as a daguerreotype.','现代数码自拍不是十九世纪早期银版摄影工艺作品。')],quiz:[Q('daguerreotype',1,1,'A daguerreotype is an early form of?',['photograph made by a nineteenth-century process','digital sound recording','printed road map'],'photograph made by a nineteenth-century process','The term names an early photographic image/process.'),Q('daguerreotype',2,1,'Why is a daguerreotype often kept behind glass?',['its delicate image is protected from damage','it must be watered like a plant','it needs sunlight to develop every day'],'its delicate image is protected from damage','Historical daguerreotypes are fragile and commonly sealed behind glass.'),Q('daguerreotype',3,1,'Which object would a photography historian call a daguerreotype?',['a cased nineteenth-century silvered-plate portrait','a photo stored only as a phone file','a painted landscape on canvas'],'a cased nineteenth-century silvered-plate portrait','A daguerreotype is a specific early photographic process/image.'),Q('daguerreotype',4,1,'The name daguerreotype honors?',['Louis Daguerre','the first person to ride a bicycle','a Greek poet named Dada'],'Louis Daguerre','The process was named for its French developer.') ]});
D('daisy',{etymology:E('daisy comes from Old English dæges ēage, literally “day’s eye,” because the flower opens in daylight and closes at night.','daisy'),contexts:[C('daisy.s1','草地植物','A white daisy with a yellow centre grew between the paving stones, and a bee landed briefly on one of its petals.','铺路石缝间长出一朵中心黄色的白色雏菊，一只蜜蜂短暂停在它的一片花瓣上。','A white daisy with a yellow centre grew between the paving stones / and a bee landed briefly / on one of its petals.','daisy 作可数名词，指常见的雏菊类花朵。','白色花瓣围绕黄色中心的植物是典型雏菊。')],mistakes:[M('The daisy had no petals or flower head and was actually a smooth grey stone.','The stone had no petals or flower head; a daisy is a flowering plant with a visible flower head.','无花瓣的石头不是雏菊，句中错把物体类别认错。')],quiz:[Q('daisy',1,1,'A common daisy often has?',['white petals around a yellow centre','blue scales and gills','a woody trunk and pine cones'],'white petals around a yellow centre','This is the familiar appearance of a daisy.'),Q('daisy',2,1,'Which setting is most likely to contain wild daisies?',['a meadow lawn','the deep ocean floor','a sealed metal cabinet'],'a meadow lawn','Daisies often grow in grass and meadows.'),Q('daisy',3,1,'The Old English source of daisy literally means?',['day’s eye','night’s stone','sun’s wheel'],'day’s eye','The historical compound was dæges ēage, “day’s eye.”'),Q('daisy',4,1,'Choose the correct phrase.',['a field of daisies','a daisy of diesel fuel','a daisy repaired the engine'],'a field of daisies','Daisies are flowers that may grow across a field.') ]});
D('damaging',{etymology:E('damaging is the present participle and adjective of damage, from Old French damage and Latin damnum “loss or harm”; it means causing harm.','damaging'),contexts:[C('damaging.s1','声誉影响','The leaked messages were damaging to the mayor’s reputation because they contradicted her public promise about the contract.','泄露的消息损害了市长的声誉，因为它们与她对合同的公开承诺相矛盾。','The leaked messages were damaging to the mayor’s reputation / because they contradicted / her public promise about the contract.','damaging 作形容词，常与 to 连用，表示对某事物造成伤害。','消息削弱公众对市长诚信的信任，符合有损害的义 s1。')],mistakes:[M('The damaging report protected the company’s reputation by disproving every allegation and confirming full compliance.','The favorable report protected the company’s reputation by disproving every allegation and confirming full compliance.','证明无违规且保护声誉的报告并非有害的 damaging report。')],quiz:[Q('damaging',1,1,'Damaging evidence is evidence that?',['harms someone’s case or reputation','proves the case conclusively in their favor','has no possible effect on the case'],'harms someone’s case or reputation','Damaging means causing harm or weakening a position.'),Q('damaging',2,1,'Which action is damaging to a wetland?',['draining it and destroying its habitat','protecting it from pollution','replanting its native marsh grasses'],'draining it and destroying its habitat','Destruction of habitat causes harm.'),Q('damaging',3,1,'In “the claim was damaging to her credibility,” damaging means?',['harmful to','helpful to','unrelated to'],'harmful to','The phrase describes an adverse effect on credibility.'),Q('damaging',4,1,'Choose the sentence where damaging is used correctly.',['The false accusation was damaging to the scientist’s reputation.','The damaging praise improved every relationship without risk.','The bridge damaging the river yesterday.'],'The false accusation was damaging to the scientist’s reputation.','A false accusation can harm a person’s reputation.') ]});
D('dancer',{etymology:E('dancer is formed from dance plus the agent suffix -er; dance came through Old French, and dancer names a person who dances.','dancer'),contexts:[C('dancer.s1','舞台演出','The dancer crossed the stage in a controlled leap, landing beside the spotlight just as the orchestra began the final refrain.','舞者以稳健的跳跃穿过舞台，恰在管弦乐队奏出最后一遍副歌时落在聚光灯旁。','The dancer crossed the stage in a controlled leap / landing beside the spotlight / just as the orchestra began the final refrain.','dancer 作可数名词，指跳舞的人或职业舞蹈演员。','舞台动作与音乐编排表明此人正在舞蹈。')],mistakes:[M('The dancer performed the entire routine while sitting motionless and never moving to the music.','The audience member watched the entire routine while sitting motionless and never moving to the music.','完全静坐且不跳舞的人是观众，不是 dancer。','confusable')],quiz:[Q('dancer',1,1,'A dancer is someone who?',['performs or takes part in dancing','repairs a broken bicycle chain','writes a court judgment'],'performs or takes part in dancing','The suffix -er marks a person who performs the activity.'),Q('dancer',2,1,'Which person is clearly a dancer?',['the performer rehearsing a ballet solo','the spectator applauding from a seat','the stage carpenter painting a set'],'the performer rehearsing a ballet solo','Rehearsing a ballet solo is dancing.'),Q('dancer',3,1,'A professional dancer may work in?',['a ballet company or touring show','a weather station as a cloud','a courtroom as a statute'],'a ballet company or touring show','Dance companies employ dancers.'),Q('dancer',4,1,'Choose the correct sentence.',['The dancer learned a new step for the performance.','The dancer step the paperwork into a folder.','The dancer was a kind of music instrument.'],'The dancer learned a new step for the performance.','A dancer learns and performs movements in a dance.') ]});
D('dandelion',{etymology:E('dandelion came through French dent de lion, literally “lion’s tooth,” referring to the jagged outline of its leaves.','dandelion'),contexts:[C('dandelion.s1','城市植物','A dandelion pushed through a crack in the pavement, and its yellow flower later became a round puff of seeds.','一株蒲公英从人行道裂缝中钻出，黄色花朵后来变成一团圆圆的种子绒球。','A dandelion pushed through a crack in the pavement / and its yellow flower later became / a round puff of seeds.','dandelion 作可数名词，指蒲公英这种草本植物。','黄色花头成熟后形成带冠毛的种子球，是蒲公英的特征。')],mistakes:[M('The dandelion was a pine tree with woody branches and cones instead of flowers.','The dandelion was a flowering herb with a yellow head and wind-dispersed seeds.','蒲公英是草本开花植物，不是有木枝和球果的松树。')],quiz:[Q('dandelion',1,1,'A dandelion is a plant known for?',['yellow flowers and fluffy seed heads','woody cones on evergreen branches','fruit growing beneath the water'],'yellow flowers and fluffy seed heads','The familiar flower later forms a puffball of seeds.'),Q('dandelion',2,1,'A child blowing on a dandelion puff sends away?',['light seeds attached to parachute-like tufts','the plant’s roots','pieces of a pine cone'],'light seeds attached to parachute-like tufts','Each seed can be carried by its feathery structure.'),Q('dandelion',3,1,'The name dandelion ultimately reflects the shape of the plant’s?',['toothed leaves','round wooden trunk','blue fruit'],'toothed leaves','French dent de lion means “lion’s tooth,” alluding to the jagged leaves.'),Q('dandelion',4,1,'Choose the accurate sentence.',['Dandelions often grow in lawns and pavement cracks.','A dandelion is a kind of marine mammal.','Dandelions are manufactured metal fasteners.'],'Dandelions often grow in lawns and pavement cracks.','The hardy flowering plant commonly grows in disturbed ground.') ]});
D('dangerous',{etymology:E('dangerous is formed from danger plus the adjective suffix -ous; danger came through Old French. The adjective means likely to cause harm or injury.','dangerous'),contexts:[C('dangerous.s1','户外安全','The ranger closed the trail because loose rocks made the narrow path dangerous after two days of heavy rain.','连续两天大雨后，松动的岩石使这条狭窄山路变得危险，护林员因此封闭了步道。','The ranger closed the trail / because loose rocks made the narrow path dangerous / after two days of heavy rain.','dangerous 作宾语补足语，说明 path 可能造成伤害。','雨后落石令行走有受伤风险，符合危险义 s1。'),C('dangerous.s2','观点风险','The editor called the rumor dangerous because it could encourage residents to blame an entire community for one person’s crime.','编辑称这则谣言很危险，因为它可能诱使居民把一个人的罪行归咎于整个社群。','The editor called the rumor dangerous / because it could encourage residents / to blame an entire community / for one person’s crime.','dangerous 可比喻修饰观点或言论，指可能造成严重社会伤害。','谣言有引发群体污名化的后果，符合言论危险义 s2。')],mistakes:[M('The flooded bridge was dangerous, but it was completely safe to cross and posed no possible risk to anyone.','The flooded bridge was dangerous, so it was unsafe to cross and posed a risk to anyone.','完全无风险的过桥情况不能同时称为 dangerous；危险一词要求存在伤害可能。')],quiz:[Q('dangerous',1,1,'A dangerous trail is one that?',['may cause injury to people using it','is guaranteed to be perfectly safe','has already been closed forever by definition'],'may cause injury to people using it','Dangerous means likely to cause harm or injury.'),Q('dangerous',2,2,'An editor calls a rumor dangerous because it could?',['incite real harm or unfair targeting','improve accurate understanding with no risk','describe a harmless shade of blue'],'incite real harm or unfair targeting','The adjective can describe harmful ideas or speech.'),Q('dangerous',3,1,'Which object is most clearly dangerous to handle?',['a live electrical wire with exposed metal','a soft cloth napkin','a sealed empty cardboard box'],'a live electrical wire with exposed metal','Exposed live wiring can cause electric shock.'),Q('dangerous',4,2,'“A dangerous stereotype” most likely means a stereotype that?',['can lead to harmful treatment of people','is simply difficult to spell','is printed on a small card'],'can lead to harmful treatment of people','The figurative use points to harmful consequences.') ]});
D('dank',{etymology:E('dank is recorded in Middle English for damp or moist conditions; its further origin is uncertain. In modern use it often suggests unpleasantly cold, clammy dampness.','dank'),contexts:[C('dank.s1','地下室环境','The dank cellar smelled of wet stone, and the boxes stored against its walls had begun to soften with moisture.','阴湿的地窖散发着湿石头的气味，靠墙存放的箱子也因受潮开始变软。','The dank cellar smelled of wet stone / and the boxes stored against its walls / had begun to soften with moisture.','dank 作定语形容词，描述令人不舒服的潮湿环境。','潮湿气味和受潮纸箱体现阴冷湿黏的环境，符合 s1。'),C('dank.s2','衣物潮气','His coat felt dank after hanging all night in the unheated entrance, so he spread it near a warm vent.','外套在没有暖气的门厅挂了一夜后摸起来湿冷，他便把它摊在暖风口旁。','His coat felt dank after hanging all night in the unheated entrance / so he spread it near a warm vent.','dank 作表语描述衣物或空气的潮湿、阴冷状态。','衣物受潮且发冷，符合“潮湿的”义 s2。')],mistakes:[M('The dank room was warm, dry, and pleasantly aired, with no trace of dampness.','The airy room was warm, dry, and pleasantly aired, with no trace of dampness.','温暖干燥、空气清新的房间与 dank 所表示的阴湿不适相反。')],quiz:[Q('dank',1,1,'A dank basement is typically?',['unpleasantly damp and chilly','sunny, dry, and warm','filled with fresh desert air'],'unpleasantly damp and chilly','Dank commonly describes cold, unpleasant dampness.'),Q('dank',2,2,'A coat feels dank when it is?',['damp and clammy','crisp and completely dry','burning hot and dusty'],'damp and clammy','The adjective can describe damp clothing or air.'),Q('dank',3,1,'Which place is most likely dank?',['a poorly ventilated cellar with wet walls','a heated room with a dehumidifier','a bright, dry rooftop at noon'],'a poorly ventilated cellar with wet walls','Poor ventilation and wet walls make the cellar damp and clammy.'),Q('dank',4,2,'Choose the strongest contrast to dank.',['dry and airy','clammy and musty','wet and chilly'],'dry and airy','Dry and airy expresses the opposite condition.') ]});
D('dapple',{etymology:E('dapple is an old English word for a mottled or spotted pattern; its deeper origin is uncertain. It also serves as a verb meaning to mark with irregular patches.','dapple'),contexts:[C('dapple.s1','马匹外观','The grey horse had a fine dapple across its flanks, with rounded darker patches scattered through the pale coat.','这匹灰马的两侧有细密斑纹，浅色皮毛间散布着圆形深色斑块。','The grey horse had a fine dapple across its flanks / with rounded darker patches / scattered through the pale coat.','dapple 作名词，指皮毛上的斑驳花纹。','浅色底毛上散落深色斑块，符合斑纹义 s1。'),C('dapple.s2','光影效果','Late sunlight dappled the garden path as it passed through the moving leaves overhead.','傍晚的阳光穿过头顶摇动的树叶，在花园小径上投下斑驳光影。','Late sunlight dappled the garden path / as it passed through the moving leaves overhead.','dapple 作及物动词，表示使表面布满不规则光斑或色斑。','叶影令小径呈现零散光斑，体现动词义 s2。')],mistakes:[M('The horse had a dappled coat of one perfectly uniform color, with no patches or spots anywhere.','The horse had a solid-colored coat of one uniform color, with no patches or spots anywhere.','均匀单色、没有斑块不能称为 dappled。','word-formation')],quiz:[Q('dapple',1,1,'A dapple on a horse is?',['a mottled patch or pattern on its coat','a saddle strap','a straight line shaved into its mane'],'a mottled patch or pattern on its coat','As a noun, dapple means a spot or mottled marking.'),Q('dapple',2,2,'Sunlight dappled the floor. What happened?',['irregular patches of light fell across it','the floor became perfectly dark','the floor was painted one even color'],'irregular patches of light fell across it','The verb describes making a surface spotted or mottled.'),Q('dapple',3,1,'Which animal might be described as having dapples?',['a grey horse with scattered darker spots','a plain white rabbit with no markings','a smooth rock with no color variation'],'a grey horse with scattered darker spots','The patches make the coat dappled.'),Q('dapple',4,2,'Choose the verb use of dapple.',['Leaves dappled the wall with shifting shade.','A dapple appeared on the horse’s flank.','The grey coat showed a dapple of spots.'],'Leaves dappled the wall with shifting shade.','Here dappled describes leaves casting mottled shade onto the wall.') ]});
D('daring',{etymology:E('daring is the present participle and adjective from dare, an Old English verb meaning to venture; as a noun it refers to boldness.','daring'),contexts:[C('daring.s1','救援行动','The daring climber crossed the exposed ridge during the rescue, securing a rope before the storm closed in.','救援时，这名勇敢的登山者穿过无遮蔽的山脊，在风暴逼近前固定好绳索。','The daring climber crossed the exposed ridge during the rescue / securing a rope / before the storm closed in.','daring 作定语形容词，描述冒险且需要勇气的行动者。','在暴风雨前穿越暴露山脊具有风险，体现勇敢义 s1。'),C('daring.s2','创意设计','The designer’s daring cut paired a deep asymmetrical collar with an unexpected strip of bright orange silk.','设计师大胆新颖的剪裁把深斜领与一条出人意料的亮橙色丝绸搭配在一起。','The designer’s daring cut paired a deep asymmetrical collar / with an unexpected strip / of bright orange silk.','daring 修饰 cut，评价设计新颖、大胆而具有冒险性。','不寻常的剪裁和配色体现创新冒险义 s2。')],mistakes:[M('Her daring escape was completely risk-free, required no courage, and followed a routine path with no obstacles.','Her routine escape was completely risk-free and followed a familiar path with no obstacles.','毫无风险且按常规路线进行的行动不体现 daring 的胆量或冒险性。')],quiz:[Q('daring',1,1,'A daring rescue is one that?',['requires courage despite real risk','is routine and involves no danger','takes place only in a classroom'],'requires courage despite real risk','Daring commonly describes bold action in risky circumstances.'),Q('daring',2,2,'A daring new design is?',['unusually bold or innovative','a copy of a common design','a hidden repair that cannot be seen'],'unusually bold or innovative','The adjective can describe adventurous novelty.'),Q('daring',3,1,'Which person acts daringly?',['a firefighter entering a risky area to rescue someone','a spectator watching from a safe seat','a clerk filing routine paperwork'],'a firefighter entering a risky area to rescue someone','The rescue calls for boldness in the face of danger.'),Q('daring',4,2,'“The artist’s daring use of color” praises the work as?',['bold and unconventional','careful but entirely ordinary','unrelated to color'],'bold and unconventional','Daring can praise unusually bold artistic choices.') ]});
D('darkroom',{etymology:E('darkroom is the compound dark + room; it names a light-controlled room used especially to develop photographic film and make prints.','darkroom'),contexts:[C('darkroom.s1','传统摄影','In the darkroom, Jo placed the exposed paper in developer under a dim red safelight and watched the image slowly appear.','在暗房里，乔在微弱红色安全灯下把曝光相纸放入显影液，看着影像慢慢浮现。','In the darkroom / Jo placed the exposed paper in developer / under a dim red safelight / and watched the image slowly appear.','darkroom 作可数名词，指冲洗胶片或相纸的避光房间。','显影液和安全灯都指向传统摄影暗房。')],mistakes:[M('The photographer exposed the undeveloped film to bright daylight inside the darkroom to keep it light-sensitive.','The photographer kept undeveloped film away from bright light in the darkroom.','暗房用于控制光线；让未冲洗材料暴露于强光会毁掉影像。')],quiz:[Q('darkroom',1,1,'A traditional photographer uses a darkroom to?',['develop film and photographic prints','bake bread in sunlight','store bicycles overnight'],'develop film and photographic prints','The room controls light during photographic processing.'),Q('darkroom',2,1,'Why is a photographic darkroom kept dark?',['undeveloped light-sensitive materials must be protected','darkness makes every camera battery recharge','the room is used only for sleeping'],'undeveloped light-sensitive materials must be protected','Uncontrolled light can expose and ruin photographic materials.'),Q('darkroom',3,1,'Which equipment might be found in a darkroom?',['developer trays and a safelight','a tennis net and referee whistle','a tractor plow'],'developer trays and a safelight','These are common tools for traditional print processing.'),Q('darkroom',4,1,'A person enlarging a negative onto paper is probably working in a?',['darkroom','dining car','greenhouse'],'darkroom','Enlarging photographic negatives is a darkroom activity.') ]});
D('darn',{etymology:E('darn, meaning mend a hole in fabric, is recorded from older forms related to dern “hidden”; its history is uncertain. It also appears as a mild euphemistic exclamation.','darn'),contexts:[C('darn.s1','衣物修补','When the wool sock wore thin at the heel, Priya darned it with matching thread so she could keep wearing it through winter.','羊毛袜的后跟磨薄后，普里娅用同色线织补起来，这样冬天还能继续穿。','When the wool sock wore thin at the heel / Priya darned it with matching thread / so she could keep wearing it through winter.','darn 作及物动词，表示用针线织补织物上的洞或磨损处。','用线修补袜子破损处是动词义 s1。'),C('darn.s2','补丁细节','A neat darn covered the small hole in the elbow of his jacket, almost matching the original weave.','他夹克肘部的小洞上有一块织补得很整齐的补片，几乎与原织纹一致。','A neat darn covered the small hole / in the elbow of his jacket / almost matching the original weave.','darn 作可数名词，指织补或织补处。','覆盖破洞的修补针脚体现名词义 s2。')],mistakes:[M('She darned the torn sock by throwing it away without sewing or repairing any part of it.','She discarded the torn sock without darning it.','直接丢弃而没有缝补不是 darn；该动词要求修补织物。')],quiz:[Q('darn',1,1,'To darn a sock is to?',['repair a hole with needle and thread','wash it in cold water','cut it into strips'],'repair a hole with needle and thread','Darn means mend a hole in knitted fabric.'),Q('darn',2,2,'A darn in a sweater is?',['the repaired area or the act of mending','a type of zipper','the sweater’s washing label'],'the repaired area or the act of mending','As a noun, darn names a repair or its stitches.'),Q('darn',3,1,'Which action is darning?',['weaving thread across a worn patch in a sock','adding a button to a coat','ironing a clean shirt'],'weaving thread across a worn patch in a sock','Darning fills or reinforces a hole with thread.'),Q('darn',4,2,'Choose the noun use of darn.',['There was a visible darn near the cuff.','She will darn the cuff tonight.','They are darning two wool socks.'],'There was a visible darn near the cuff.','Here darn names the repaired spot.') ]});
D('dateline',{etymology:E('dateline combines date and line; in journalism it is the line identifying where and when a report was filed. The same compound also names the International Date Line.','dateline'),contexts:[C('dateline.s1','新闻格式','The report began with the dateline “NAIROBI, Tuesday,” before describing the election results and the crowds outside parliament.','报道先以“内罗毕，星期二”作为日期行，随后介绍选举结果和议会外的人群。','The report began with the dateline “NAIROBI, Tuesday” / before describing the election results / and the crowds outside parliament.','dateline 作可数名词，指新闻开头标明地点和日期的行。','地点加日期位于新闻开头，符合新闻日期行义 s1。'),C('dateline.s2','国际日期变更','A flight crossing the International Date Line eastward may arrive on a calendar date earlier than the one on which it departed.','飞机向东跨越国际日期变更线后，抵达时的日历日期可能早于出发日期。','A flight crossing the International Date Line eastward / may arrive on a calendar date earlier / than the one on which it departed.','International Date Line 是固定专名，指地球上日期转换的参考线。','跨越该线会调整日历日期，体现地理义 s2。')],mistakes:[M('A newspaper dateline identifies the article’s font size but gives no place or date.','A newspaper dateline identifies where and when the report was filed.','新闻日期行标地点和日期，不是字体大小说明。')],quiz:[Q('dateline',1,1,'A newspaper dateline usually gives?',['the place and date associated with a report','the editor’s shoe size','the newspaper’s paper weight'],'the place and date associated with a report','Journalistic datelines identify the report’s location and date.'),Q('dateline',2,2,'Crossing the International Date Line can change the?',['calendar date shown locally','length of the aircraft’s wings','color of the ocean'],'calendar date shown locally','The line marks a transition between calendar dates.'),Q('dateline',3,1,'Where would a reader normally see a news dateline?',['near the beginning of a report','only on the back cover of a novel','in the middle of a weather map legend'],'near the beginning of a report','A dateline commonly precedes the news story text.'),Q('dateline',4,2,'The International Date Line is relevant to?',['timekeeping and calendar dates across the globe','spelling words with silent letters','measuring the depth of a lake'],'timekeeping and calendar dates across the globe','Crossing the line changes the local calendar date.') ]});
D('datum',{etymology:E('datum is Latin for “something given,” the neuter past participle of dare “give”; English uses it for one item of information or a reference point.','datum'),contexts:[C('datum.s1','科学记录','The researcher checked each datum against the original field notes before combining the observations into a table.','研究人员把每一项数据都与原始野外笔记核对后，才将观察结果汇总成表格。','The researcher checked each datum against the original field notes / before combining the observations / into a table.','datum 是单数名词，指一项信息；其常见复数为 data。','each 后接单数 datum，表示逐项核验信息。'),C('datum.s2','测绘基准','Surveyors used the brass marker as a datum, measuring the new road’s elevation relative to that fixed reference point.','测绘人员把黄铜标记用作基准点，以该固定参照测量新道路的海拔。','Surveyors used the brass marker as a datum / measuring the new road’s elevation / relative to that fixed reference point.','datum 可数名词可指测量所依据的固定参考点。','标记用来比较高程，是测绘基准义 s2。')],mistakes:[M('The report called one individual measurement “many data” and treated datum as a plural noun.','The report called one individual measurement a datum and used data for the plural.','datum 是单数形式；通常以 data 表示多个数据项。','grammar')],quiz:[Q('datum',1,1,'One datum is?',['a single item of information','a collection of many unrelated books','the plural of data'],'a single item of information','Datum is the singular counterpart of data.'),Q('datum',2,2,'A survey datum is a?',['fixed reference point for measurements','single line of newspaper text','type of bicycle pedal'],'fixed reference point for measurements','In surveying, a datum provides a reference for measurements.'),Q('datum',3,1,'Choose the grammatically standard phrase for one observation.',['one datum','one data','one datas'],'one datum','Datum is the singular noun.'),Q('datum',4,2,'The engineer measured height above a datum. The datum served as?',['the reference level','the measured building material','the city’s weather forecast'],'the reference level','A datum can be a fixed reference level or point.') ]});
D('dauntless',{etymology:E('dauntless is formed from daunt, through Old French danter “tame or subdue,” plus -less “without”; it means not intimidated or discouraged.','dauntless'),contexts:[C('dauntless.s1','救灾志愿者','The dauntless volunteers entered the damaged village at dawn, distributing clean water despite the unstable roads.','无畏的志愿者黎明时进入受灾村庄，尽管道路不稳仍坚持分发饮用水。','The dauntless volunteers entered the damaged village at dawn / distributing clean water / despite the unstable roads.','dauntless 作定语形容词，修饰 volunteers，强调不因危险而退缩。','志愿者冒着道路风险救灾，体现无畏义 s1。'),C('dauntless.s2','长期抗争','Her dauntless resolve kept the legal campaign moving even after repeated delays and several setbacks.','即使屡遭拖延和挫折，她坚韧不屈的决心仍推动法律行动继续进行。','Her dauntless resolve kept the legal campaign moving / even after repeated delays / and several setbacks.','dauntless 修饰 resolve，强调面对挫折仍不气馁。','决心经受反复挫折仍保持坚定，对应不屈不挠义 s2。')],mistakes:[M('The dauntless crew abandoned the rescue at the first minor inconvenience because they were too frightened to continue.','The easily discouraged crew abandoned the rescue at the first minor inconvenience.','遇到轻微不便便因害怕而放弃，不体现 dauntless 的无畏坚毅。','word-formation')],quiz:[Q('dauntless',1,1,'A dauntless person is?',['not easily frightened or intimidated','quickly discouraged by every obstacle','unable to make a decision'],'not easily frightened or intimidated','Dauntless means fearless or undaunted.'),Q('dauntless',2,2,'Dauntless resolve helps someone?',['persist despite setbacks','forget every goal at the first delay','avoid making any effort'],'persist despite setbacks','The second sense stresses steadfast determination.'),Q('dauntless',3,1,'Which action seems dauntless?',['rescuers entering a dangerous area to help trapped residents','a visitor leaving a quiet room after hearing a clock','a runner stopping before the race begins'],'rescuers entering a dangerous area to help trapped residents','They proceed despite danger and fear.'),Q('dauntless',4,2,'After many failures, her dauntless effort means she?',['continues without giving up','decides success is impossible and quits','forgets why she began'],'continues without giving up','Dauntless effort remains firm despite discouragement.') ]});
D('dawdle',{etymology:E('dawdle is an English verb recorded from the eighteenth century; its origin is uncertain. It means to waste time by moving or acting slowly.','dawdle'),contexts:[C('dawdle.s1','赶车出发','If we dawdle over breakfast, we will miss the early train and have to wait another hour at the station.','如果我们吃早饭时磨蹭，就会错过早班火车，还得在车站再等一小时。','If we dawdle over breakfast / we will miss the early train / and have to wait another hour at the station.','dawdle 作不及物动词，常接 over + 事情，表示在某事上拖延。','早餐时拖延导致误车，符合磨蹭义。')],mistakes:[M('The crew dawdled through the evacuation by running immediately and clearing the building in seconds.','The crew hurried through the evacuation by running immediately and clearing the building in seconds.','立刻奔跑并迅速完成并非 dawdle；该词表示拖延、慢吞吞。','confusable')],quiz:[Q('dawdle',1,1,'To dawdle is to?',['waste time by moving or acting slowly','finish a task with great speed','measure a distance carefully'],'waste time by moving or acting slowly','Dawdle means linger or delay unnecessarily.'),Q('dawdle',2,1,'“Don’t dawdle over lunch” means?',['do not take so long that you delay what follows','do not eat lunch at all','eat lunch in complete silence'],'do not take so long that you delay what follows','Dawdle over something is to be slow about it.'),Q('dawdle',3,1,'Which child is dawdling?',['the child slowly stops at every shop window while walking home','the child runs straight home in five minutes','the child arrives early and waits quietly'],'the child slowly stops at every shop window while walking home','Repeated slow stops make the child late.'),Q('dawdle',4,1,'Choose the natural use.',['We dawdled along the path and arrived after sunset.','We dawdled the door shut with a key.','The dawdle was a precise unit of weight.'],'We dawdled along the path and arrived after sunset.','Dawdle is intransitive here and describes slow progress.') ]});
D('dawning',{etymology:E('dawning is formed from dawn plus -ing; dawn is an Old English word for the first appearance of daylight and also the beginning of a period.','dawning'),contexts:[C('dawning.s1','清晨景色','At dawning, a thin strip of pink light appeared above the eastern hills while the valley below remained dark.','黎明时，东边山丘上方出现一道淡粉色的光，而下方山谷仍然漆黑。','At dawning / a thin strip of pink light appeared above the eastern hills / while the valley below remained dark.','dawning 作时间名词，指天刚亮、黎明时分。','天边初现晨光而山谷仍暗，符合黎明义 s1。'),C('dawning.s2','历史阶段','The dawning of the digital era brought new tools for storing information, although early computers remained large and expensive.','数字时代的开端带来了储存信息的新工具，尽管早期计算机仍然体积庞大且价格昂贵。','The dawning of the digital era brought new tools / for storing information / although early computers remained large and expensive.','the dawning of + 时期/事物表示其开始出现或萌发。','新工具标志着数字时代开始形成，符合开端义 s2。')],mistakes:[M('The dawning of the digital era happened after it had already ended and all its technologies disappeared.','The end of the digital era happened after it had already run its course.','dawning 指开端或初现，不可能指一个时代结束之后。','word-formation')],quiz:[Q('dawning',1,1,'Dawning is the time when?',['daylight first begins to appear','the sun has set and midnight is over','a storm reaches its strongest point'],'daylight first begins to appear','Dawning is daybreak or the first light of day.'),Q('dawning',2,2,'The dawning of a new era is?',['its beginning or first emergence','the final event after it ends','a measurement of its length'],'its beginning or first emergence','The word is used figuratively for the start of a period.'),Q('dawning',3,1,'A traveler leaves at dawning. The traveler leaves?',['around daybreak','at the middle of the night only','after the sun has set'],'around daybreak','Dawning refers to the first light of morning.'),Q('dawning',4,2,'“The dawning of public awareness” means awareness?',['was beginning to emerge','had vanished long ago','was measured in inches'],'was beginning to emerge','The figurative sense marks a beginning.') ]});
D('dazzlingly',{etymology:E('dazzlingly is formed from dazzling, the -ing form of dazzle, plus the adverb suffix -ly; it means in a brilliantly bright or impressively striking way.','dazzlingly'),contexts:[C('dazzlingly.s1','舞台灯光','The mirrored costume shone dazzlingly beneath the spotlights, forcing the stage crew to lower the beams between scenes.','镜面服装在聚光灯下耀眼地闪亮，舞台工作人员不得不在两场戏之间调低光束。','The mirrored costume shone dazzlingly beneath the spotlights / forcing the stage crew / to lower the beams between scenes.','dazzlingly 修饰 shone，表示光线极其耀眼。','镜面反射强光使灯光过亮，体现耀眼义 s1。')],mistakes:[M('The lamp glowed dazzlingly, but its light was so dim that nobody could see it even in a dark room.','The lamp glowed faintly, and its light was too dim for anyone to see.','昏暗到不可见的光不能称为 dazzlingly bright。')],quiz:[Q('dazzlingly',1,1,'A surface shines dazzlingly when it shines?',['so brightly that it may be hard to look at','too dimly to see','only in complete darkness'],'so brightly that it may be hard to look at','Dazzlingly is the adverb form of dazzlingly bright.'),Q('dazzlingly',2,1,'“She was dazzlingly clever” means she was?',['extraordinarily impressive in intelligence','unable to solve a simple problem','wearing a shiny uniform'],'extraordinarily impressive in intelligence','Dazzlingly can intensify a striking quality figuratively.'),Q('dazzlingly',3,1,'Which use is literal?',['The ice glittered dazzlingly in direct sun.','His argument was dazzlingly persuasive.','The novel was dazzlingly original.'],'The ice glittered dazzlingly in direct sun.','The sentence describes intense reflected light.'),Q('dazzlingly',4,1,'Which sentence uses the figurative sense?',['The dancer gave a dazzlingly graceful performance.','The headlights shone dazzlingly into the lens.','The snow reflected light dazzlingly.'],'The dancer gave a dazzlingly graceful performance.','Here the adverb intensifies an impressive quality rather than brightness.') ]});
D('dearth',{etymology:E('dearth derives from Old English deore “dear, precious” and the noun-forming -th; the word shifted toward scarcity, especially a lack of something valued.','dearth'),contexts:[C('dearth.s1','公共资源','A dearth of affordable apartments pushed many nurses to live far outside the city and commute before each early shift.','可负担公寓的匮乏迫使许多护士住在城外很远的地方，每次早班前都要长途通勤。','A dearth of affordable apartments / pushed many nurses to live far outside the city / and commute before each early shift.','a dearth of + 名词表示某物缺乏或数量不足。','住房供给不够，导致护士不得不远距离通勤，体现缺乏义 s1。'),C('dearth.s2','粮食短缺','The region suffered a dearth after three failed harvests, and relief ships delivered grain to villages along the coast.','连续三次歉收后，该地区遭遇粮食短缺，救援船向沿海村庄运送谷物。','The region suffered a dearth after three failed harvests / and relief ships delivered grain / to villages along the coast.','dearth 可指严重的粮食不足或饥馑。','歉收和运粮救济指向粮食匮乏义 s2。')],mistakes:[M('The town faced a dearth of clean water even though every reservoir was full and residents had unlimited supplies.','The town faced a plentiful supply of clean water because every reservoir was full.','水库充足、供应无限与 dearth of water（缺水）相矛盾。')],quiz:[Q('dearth',1,1,'A dearth of evidence means?',['too little evidence is available','evidence is abundant','the evidence has been translated'],'too little evidence is available','Dearth means a scarcity or lack.'),Q('dearth',2,2,'A historical account of dearth after failed crops describes?',['a severe shortage of food','an unusually large harvest','a new farming tool'],'a severe shortage of food','The word can refer to famine or food scarcity.'),Q('dearth',3,1,'Which phrase uses dearth correctly?',['a dearth of experienced nurses','a dearth of extra supplies when warehouses are overflowing','a dearth of rain during a record flood'],'a dearth of experienced nurses','The phrase names a shortage of people with needed experience.'),Q('dearth',4,2,'Which situation most clearly signals a food dearth?',['villages receive emergency grain after repeated crop failures','farmers harvest more wheat than they can store','markets are filled with fresh produce'],'villages receive emergency grain after repeated crop failures','Crop failures and emergency grain indicate scarcity.') ]});
D('debacle',{etymology:E('debacle entered English from French débâcle, “a breaking up or collapse,” originally associated with ice breaking loose; it now means a sudden disastrous failure.','debacle'),contexts:[C('debacle.s1','活动组织失败','The outdoor concert became a debacle when the stage flooded, the power failed, and thousands of visitors were turned away.','舞台被淹、电力中断、数千名观众被拒之门外，这场户外音乐会成了一次彻底的惨败。','The outdoor concert became a debacle / when the stage flooded / the power failed / and thousands of visitors were turned away.','debacle 作可数名词，指一连串造成彻底失败的灾难性事件。','多个关键环节崩溃导致活动全面失败，符合 s1。')],mistakes:[M('The launch was a debacle because every system worked perfectly, guests arrived on time, and the event exceeded all goals.','The launch was a success because every system worked perfectly and the event exceeded all goals.','顺利且超额达标的活动不是灾难性失败 debacle。')],quiz:[Q('debacle',1,1,'A political debacle is?',['a disastrous failure','a routine private meeting','a carefully kept secret with no outcome'],'a disastrous failure','Debacle denotes a complete or humiliating failure.'),Q('debacle',2,1,'Which event could be called a debacle?',['a festival where the stage collapses and the evacuation plan fails','a well-run festival with no delays','a quiet rehearsal attended by three people'],'a festival where the stage collapses and the evacuation plan fails','The failures combine into a disastrous event.'),Q('debacle',3,1,'Calling the negotiations a debacle suggests they?',['ended in a major failure','produced a perfect agreement','were never scheduled'],'ended in a major failure','The noun emphasizes a disastrous outcome.'),Q('debacle',4,1,'Choose the closest meaning of debacle.',['fiasco','triumph','routine'],'fiasco','A fiasco is a complete failure, like a debacle.') ]});
D('debatable',{etymology:E('debatable is formed from debate, ultimately from French débattre “fight or discuss,” plus -able; it means open to discussion or questionable.','debatable'),contexts:[C('debatable.s1','学术讨论','Whether the early settlement was permanent is debatable, since the evidence consists of a few scattered tools and no year-round dwellings.','早期定居点是否长期存在仍有讨论余地，因为证据只有零散工具，没有全年居所。','Whether the early settlement was permanent is debatable / since the evidence consists of a few scattered tools / and no year-round dwellings.','debatable 作表语形容词，表示某判断尚未定论、可继续讨论。','证据有限，学者可以对是否永久居住提出不同论证，符合 s1。'),C('debatable.s2','质量评价','The claim that the cheap hinge would last fifty years was debatable, given its thin metal and loose joints.','考虑到合页金属很薄、连接又松散，“它能用五十年”的说法值得怀疑。','The claim that the cheap hinge would last fifty years was debatable / given its thin metal / and loose joints.','debatable 表示可质疑、成问题的判断。','材料和结构缺陷削弱寿命说法的可信度，符合 s2。')],mistakes:[M('The result was debatable because every independent test confirmed it beyond any possible disagreement.','The result was beyond dispute because every independent test confirmed it.','已被独立测试确证到毫无争议的结果不再是 debatable。','confusable')],quiz:[Q('debatable',1,1,'A debatable interpretation is one that?',['reasonable people can discuss or dispute','has been proven impossible to question','cannot be expressed in words'],'reasonable people can discuss or dispute','The first sense is open to argument or discussion.'),Q('debatable',2,2,'A debatable claim may be?',['questionable or doubtful','certainly true in every case','a person who debates professionally'],'questionable or doubtful','The second sense expresses doubt about whether a claim is sound.'),Q('debatable',3,1,'Which question is most debatable?',['whether the ambiguous evidence proves a settlement was permanent','whether two plus two equals four under ordinary arithmetic','whether a triangle has three sides by definition'],'whether the ambiguous evidence proves a settlement was permanent','Limited evidence leaves the interpretation open to discussion.'),Q('debatable',4,2,'“It is debatable whether the repair will last” implies?',['its durability is uncertain','the repair has already lasted forever','the repair is a debate club'],'its durability is uncertain','The phrase signals doubt about the claim.') ]});
D('debauch',{etymology:E('debauch came from French débaucher, originally “lead away from work,” and developed senses of corrupting or indulging excessively; as a noun it can name a wild revel.','debauch'),contexts:[C('debauch.s1','道德败坏','The novel shows a powerful patron using money to debauch young artists, drawing them away from their principles and exploiting their dependence.','小说描写一位有权势的赞助人用金钱腐化年轻艺术家，使他们背弃原则并利用他们的依赖处境。','The novel shows a powerful patron using money / to debauch young artists / drawing them away from their principles / and exploiting their dependence.','debauch 作及物动词，意为使人堕落或腐化。','赞助人诱使艺术家放弃原则并加以利用，体现腐化义 s1。'),C('debauch.s2','纵酒狂欢','After the election, the defeated leader hosted a debauch that lasted until dawn, with music, wine, and guests crowding every room.','选举失利后，这位落选领导人举办了一场通宵纵乐的宴会，音乐、酒水和宾客挤满了每个房间。','After the election / the defeated leader hosted a debauch / that lasted until dawn / with music, wine, and guests crowding every room.','debauch 作可数名词，指放纵狂欢或纵酒作乐的聚会。','通宵饮酒、音乐喧闹的聚会符合 s2。')],mistakes:[M('The mentor debauched the trainees by teaching them honesty, self-control, and respect for others.','The mentor disciplined the trainees by teaching them honesty, self-control, and respect for others.','培养诚实克己不是 debauch；该动词表示使人堕落或纵欲。')],quiz:[Q('debauch',1,1,'To debauch someone is to?',['corrupt or lead the person into immoral excess','teach the person careful self-discipline','give the person a formal promotion'],'corrupt or lead the person into immoral excess','The verb means corrupt morally or indulge to excess.'),Q('debauch',2,2,'A debauch that lasts until dawn is?',['a wild, excessive revel','a quiet legal hearing','a scientific study of cells'],'a wild, excessive revel','As a noun, debauch can mean an unrestrained party or indulgence.'),Q('debauch',3,1,'Which situation best fits the verb debauch?',['a corrupt official encourages aides to misuse public funds','a coach teaches players fair rules','a doctor helps a patient recover'],'a corrupt official encourages aides to misuse public funds','The action corrupts others into wrongdoing.'),Q('debauch',4,2,'Choose the noun use of debauch.',['The travelers joined a debauch at the inn.','The official tried to debauch the witness.','The novel depicts a patron who debauched artists.'],'The travelers joined a debauch at the inn.','Here it names a revel or episode of excessive indulgence.') ]});
D('debilitate',{etymology:E('debilitate comes from Latin debilitare, from debilis “weak”; the verb means to make a person or system weak or less effective.','debilitate'),contexts:[C('debilitate.s1','病后恢复','A prolonged infection can debilitate an otherwise healthy patient, leaving her too weak to return to work for several weeks.','长期感染可能使原本健康的患者衰弱，令她数周内虚弱到无法复工。','A prolonged infection can debilitate an otherwise healthy patient / leaving her too weak / to return to work for several weeks.','debilitate 作及物动词，宾语是被削弱的人或系统。','感染造成持续体力衰退，符合使衰弱义。')],mistakes:[M('The illness debilitated the runner by making him stronger, faster, and more energetic than before.','The illness debilitated the runner by leaving him weak and unable to train.','变得更强壮精力充沛与 debilitate（使虚弱）意义相反。','word-formation')],quiz:[Q('debilitate',1,1,'A disease that debilitates a patient?',['makes the patient weak','instantly increases the patient’s strength','teaches the patient a language'],'makes the patient weak','Debilitate means to weaken physically or mentally.'),Q('debilitate',2,1,'Which event could debilitate a workforce?',['a prolonged illness that leaves many employees unable to work','a short paid break that restores energy','a successful training session'],'a prolonged illness that leaves many employees unable to work','The illness reduces the workers’ strength and effectiveness.'),Q('debilitate',3,1,'Choose the sentence that uses debilitate correctly.',['Months of poor sleep debilitated the athlete.','The vitamin debilitated the team by restoring their energy.','She debilitated the door with a key.'],'Months of poor sleep debilitated the athlete.','Poor sleep can weaken the athlete.'),Q('debilitate',4,1,'The closest opposite of debilitate is?',['strengthen','weaken','exhaust'],'strengthen','To strengthen is to make more capable, the reverse of debilitating.') ]});
D('debility',{etymology:E('debility derives from Latin debilitas “weakness,” from debilis “weak”; it names a state of physical or mental weakness.','debility'),contexts:[C('debility.s1','老年照护','The physician attributed the patient’s debility to months of poor nutrition and arranged a gradual rehabilitation plan.','医生把患者的虚弱归因于数月营养不良，并安排了循序渐进的康复计划。','The physician attributed the patient’s debility to months of poor nutrition / and arranged a gradual rehabilitation plan.','debility 作不可数名词，指体力或身心衰弱状态。','营养不足导致体弱，需要康复，符合 s1。')],mistakes:[M('The patient’s debility gave her unusual strength and allowed her to lift heavier weights than ever.','The patient’s recovery gave her unusual strength and allowed her to lift heavier weights than before.','体力增强并能举重不符合 debility 所指的虚弱状态。','word-formation')],quiz:[Q('debility',1,1,'Debility is a condition of?',['weakness','exceptional physical power','a temporary change in weather'],'weakness','Debility is a noun for weakness or feebleness.'),Q('debility',2,1,'A patient recovering from debility may need?',['rest and gradual rehabilitation','a race against professional athletes','less food and no medical care'],'rest and gradual rehabilitation','Recovery from weakness often involves supportive rehabilitation.'),Q('debility',3,1,'Which sentence uses debility correctly?',['The illness left her with severe debility.','The debility made the athlete stronger overnight.','He debility the machine into a new shape.'],'The illness left her with severe debility.','Debility names the weakness caused by illness.'),Q('debility',4,1,'Which word is closest in meaning to debility?',['frailty','vigor','strength'],'frailty','Frailty and debility both refer to weakness.') ]});
D('debtor',{etymology:E('debtor is formed from debt plus the agent suffix -or; debt came through Old French from Latin debitum “something owed,” from debere “owe.”','debtor'),contexts:[C('debtor.s1','贷款合同','The debtor made the final payment on Friday, and the lender issued a letter confirming that the balance had been cleared.','债务人星期五付清了最后一笔款项，贷款方随后出具证明，确认余额已结清。','The debtor made the final payment on Friday / and the lender issued a letter / confirming that the balance had been cleared.','debtor 作可数名词，指负有偿还债务义务的人或机构。','付款一方偿还欠款，符合债务人义 s1。')],mistakes:[M('The debtor had lent the bank money and was waiting for the bank to repay her loan.','The creditor had lent the bank money and was waiting for the bank to repay her loan.','向他人出借资金并有权收回的是 creditor；debtor 是欠款的一方。','confusable')],quiz:[Q('debtor',1,1,'A debtor is the person or organization that?',['owes money','is owed money','issues a library card'],'owes money','A debtor has an outstanding obligation to repay.'),Q('debtor',2,1,'If a company borrows from a bank, the company is the?',['debtor','creditor','auditor'],'debtor','The borrower owes repayment, so it is the debtor.'),Q('debtor',3,1,'Which role contrasts with debtor?',['creditor','borrower','obligor'],'creditor','A creditor is owed money; a debtor owes it.'),Q('debtor',4,1,'A debtor pays an installment to?',['the creditor or lender','a person who owes the debtor nothing','the company’s competitor'],'the creditor or lender','Repayment goes to the party to whom the debt is owed.') ]});
D('decadence',{etymology:E('decadence came through French décadence from Latin decadere “fall away,” formed from de- and cadere “fall”; it can mean moral excess or decline.','decadence'),contexts:[C('decadence.s1','生活风气','The essay criticized the court’s decadence, describing endless banquets and luxury purchased while nearby families struggled to find bread.','这篇文章批评宫廷的奢靡腐化：无休止的宴席和豪奢开销与附近家庭买不起面包形成鲜明对照。','The essay criticized the court’s decadence / describing endless banquets and luxury / purchased while nearby families struggled to find bread.','decadence 作不可数名词，指过度奢侈或道德上的颓废。','沉溺奢华且漠视贫困，符合奢靡颓废义 s1。'),C('decadence.s2','帝国衰落','Some historians dispute whether the empire’s decadence caused its collapse, pointing instead to military pressure and administrative failure.','一些历史学家质疑帝国的衰落是否导致其崩溃，转而指出军事压力和行政失灵。','Some historians dispute whether the empire’s decadence caused its collapse / pointing instead to military pressure / and administrative failure.','decadence of an institution can denote its gradual deterioration or decline.','帝国在制度与力量上的衰退被讨论为崩溃原因，符合 s2。')],mistakes:[M('The court’s decadence consisted of modest living, careful public spending, and refusing all forms of luxury.','The court’s austerity consisted of modest living, careful public spending, and refusing luxury.','节俭克制与 decadence 的奢靡或衰落含义相反。')],quiz:[Q('decadence',1,1,'A writer condemns social decadence when criticizing?',['excessive luxury and moral decline','careful modest living','a newly opened school'],'excessive luxury and moral decline','The first sense combines excess and moral deterioration.'),Q('decadence',2,2,'An empire’s decadence may refer to its?',['gradual decline or deterioration','rapid and healthy growth','single calendar date'],'gradual decline or deterioration','The historical sense is a process of decline.'),Q('decadence',3,1,'Which scene best illustrates decadence?',['lavish feasts while the ruling class ignores widespread hunger','a town sharing food during a famine','an office saving energy and public funds'],'lavish feasts while the ruling class ignores widespread hunger','Indulgent luxury amid need is commonly called decadence.'),Q('decadence',4,2,'Choose the sense about institutional decline.',['The decadence of the empire weakened its administration.','The decadent nobles wore jeweled robes.','The party was an evening of decadence.'],'The decadence of the empire weakened its administration.','Here decadence names the empire’s deterioration.') ]});
D('decadent',{etymology:E('decadent derives from French décadent, from décadence and ultimately Latin decadere “fall away”; it describes decline or excessive self-indulgence and can name a person associated with it.','decadent'),contexts:[C('decadent.s1','饮食描写','The pastry chef made a decadent chocolate tart with a thick ganache centre and a layer of salted caramel.','糕点师做了一款奢华浓郁的巧克力挞，中心是厚厚的甘纳许，上面还有一层咸焦糖。','The pastry chef made a decadent chocolate tart / with a thick ganache centre / and a layer of salted caramel.','decadent 修饰 dessert 时常表示极其丰盛、放纵或奢华。','厚重巧克力和咸焦糖呈现浓烈奢侈感，符合形容词 s1。'),C('decadent.s2','文化人物','The critic described the poet as a decadent who rejected conventional morality and celebrated artificial beauty.','评论家称这位诗人是颓废派人物，他拒绝传统道德并推崇人工之美。','The critic described the poet as a decadent / who rejected conventional morality / and celebrated artificial beauty.','decadent 可作可数名词，指与颓废主义/颓废生活相关的人。','人物被归入颓废派，体现名词义 s2。')],mistakes:[M('The decadent banquet was a plain bowl of rice and water served without luxury, excess, or indulgence.','The modest banquet was a plain bowl of rice and water served without luxury or excess.','朴素清淡的餐食不符合 decadent 在饮食语境中“奢华丰盛”的用法。')],quiz:[Q('decadent',1,1,'A decadent dessert is likely to be?',['rich, luxurious, and indulgent','plain and almost tasteless','a person who studies cells'],'rich, luxurious, and indulgent','The adjective often describes lavish, rich food.'),Q('decadent',2,2,'A Decadent in literary history is?',['a person associated with decadence or the Decadent movement','a debtor who pays a bill','a scientist studying cytoplasm'],'a person associated with decadence or the Decadent movement','The noun can name a participant in a cultural movement.'),Q('decadent',3,1,'Which is a figurative use of decadent?',['a decadent lifestyle of conspicuous luxury','a decadent that criticized the poem','decadent means a calendar date'],'a decadent lifestyle of conspicuous luxury','The adjective describes indulgent luxury.'),Q('decadent',4,2,'Choose the noun use.',['The decadent gathered with other writers at the salon.','The decadent meal contained chocolate and cream.','The city entered a decadent period.'],'The decadent gathered with other writers at the salon.','Here decadent names a person, not a quality or period.') ]});
D('decapitate',{etymology:E('decapitate derives from Late Latin decapitare, de- “off” plus caput “head”; it means to remove a person’s or animal’s head.','decapitate'),contexts:[C('decapitate.s1','历史刑罚','The history exhibit explained that officials once used an executioner’s sword to decapitate condemned prisoners.','历史展览说明，过去官员曾用刽子手的剑将被判刑的囚犯斩首。','The history exhibit explained / that officials once used an executioner’s sword / to decapitate condemned prisoners.','decapitate 作及物动词，宾语是被斩首的人或动物。','语境直接描述以剑移除头部的刑罚，符合词义。')],mistakes:[M('The executioner decapitated the prisoner by gently placing a hat on the prisoner’s head and causing no injury.','The executioner covered the prisoner’s head with a hat and caused no injury.','戴帽子不会移除头部；decapitate 具有明确的斩首义。')],quiz:[Q('decapitate',1,1,'To decapitate someone is to?',['remove the person’s head','remove the person’s shoes','give the person a haircut'],'remove the person’s head','The verb specifically means behead.'),Q('decapitate',2,1,'Which sentence uses decapitate accurately?',['The executioner decapitated the statue’s headless figure in the legend.','The barber decapitated the customer by trimming his hair.','The tailor decapitated a shirt by sewing on a collar.'],'The executioner decapitated the statue’s headless figure in the legend.','The verb refers to removing a head; a legend may describe that act.'),Q('decapitate',3,1,'The prefix de- in decapitate contributes the idea of?',['removal or taking away','repetition','small size'],'removal or taking away','De- is associated here with taking the head off.'),Q('decapitate',4,1,'Which word is closest in meaning to decapitate?',['behead','decorate','rehabilitate'],'behead','Behead is the direct synonym.') ]});
D('decease',{etymology:E('decease came through Old French dece(s), from Latin decedere “depart or die,” de- “away” plus cedere “go”; the noun is formal and the verb is rare.','decease'),contexts:[C('decease.s1','遗嘱条款','The trust stated that the property would pass to the named beneficiaries upon the decease of its owner.','信托文件规定，所有人去世后，财产将转给列明的受益人。','The trust stated / that the property would pass to the named beneficiaries / upon the decease of its owner.','decease 作正式名词，常用于 upon/on the decease of 某人。','财产在所有人死亡时转移，符合正式法律用语 s1。'),C('decease.s2','旧式记述','The parish record noted that the elderly sailor deceased in the spring of 1891, after returning from his final voyage.','教区记录记载，这位年长水手于 1891 年春天去世，此前刚结束最后一次航行。','The parish record noted / that the elderly sailor deceased in the spring of 1891 / after returning from his final voyage.','decease 作动词时为不及物用法，现代英语中罕见而正式/古旧。','记录以古旧正式动词表示死亡，符合 s2。')],mistakes:[M('The contract said the estate would transfer upon the decease of the owner, meaning on the owner’s birthday while still alive.','The contract said the estate would transfer upon the decease of the owner, meaning when the owner died.','decease 指死亡，不是仍在世时的生日。')],quiz:[Q('decease',1,1,'“Upon her decease” means?',['when she died','on her wedding day','after she recovered from illness'],'when she died','Decease is a formal noun for death.'),Q('decease',2,2,'The old record says “he deceased in 1891.” Here deceased means he?',['died','moved to another house','was born'],'died','As a rare verb, decease means to die.'),Q('decease',3,1,'Where is the noun decease most likely to appear?',['a formal will or legal document','a casual recipe for soup','a bicycle repair manual'],'a formal will or legal document','The noun is chiefly formal or legal.'),Q('decease',4,2,'Choose the rare verb use of decease.',['The monarch deceased before the treaty was signed.','The monarch’s decease was recorded.','The document mentions a date of decease.'],'The monarch deceased before the treaty was signed.','The sentence uses deceased as a past-tense intransitive verb.') ]});

})();
